INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(141, 'Juruteknik Mesin Ladang', 'Juruteknik yang membaiki mesin dan jentera di ladang kelapa sawit (watak rekaan).', 'Menjaga mesin ladang supaya ekonomi komersial berjalan lancar.', 'juruteknik_mesin_ladang_sawit.png'),
(142, 'Inspektor Kilang Automotif', 'Inspektor yang memeriksa mutu kereta dan motosikal di kilang (watak rekaan).', 'Memastikan barangan buatan Malaysia lulus pemeriksaan mutu.', 'inspektor_kilang_automotif.png'),
(143, 'Pemilik Kedai Jenama Malaysia', 'Pemilik kedai yang menjual barangan jenama Malaysia dengan penuh bangga (watak rekaan).', 'Memperkenalkan produk pertanian, petroleum dan automotif buatan Malaysia kepada pelanggan.', 'peniaga_rumah_kedai.png'),
(144, 'Pak Tani Dahulu', 'Petani tua yang masih setia dengan cangkul dan sabit (watak rekaan).', 'Mewakili ekonomi tradisional yang dijalankan kecil-kecilan.', 'petani_lama.png'),
(145, 'Petani Moden', 'Petani yang mengusahakan ladang dengan mesin dan jentera penuai (watak rekaan).', 'Mewakili ekonomi komersial secara perladangan.', 'petani.png'),
(146, 'Penoreh Getah', 'Penoreh getah yang peramah dan rajin bekerja (watak rekaan).', 'Mewakili industri getah dan kelapa sawit.', 'penoreh_getah.png'),
(147, 'Jurutera Pelantar Minyak', 'Jurutera yang bertugas di pelantar minyak di tengah laut (watak rekaan).', 'Mewakili industri petroleum dan gas.', 'jurutera_pelantar_minyak.png'),
(148, 'Pemandu Pelancong', 'Pemandu pelancong yang ramah dan bersemangat bercerita tentang negara (watak rekaan).', 'Mewakili industri pelancongan dan kempen Tahun Melawat Malaysia.', 'gadis_sarawak.png'),
(149, 'Peniaga E-Dagang', 'Peniaga yang menjual barangan melalui telefon dan laman web (watak rekaan).', 'Mewakili perdagangan e-dagang yang semakin berkembang.', 'ibu_kini.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(801, 'Dari Cangkul ke Jentera: Kembara Juruteknik', 8, 'Masuki peranan juruteknik mesin ladang yang mengembara dari sawah bercangkul ke ladang moden. Kau mengenali ekonomi tradisional dan komersial dalam pertanian dan perlombongan serta industri getah dan kelapa sawit.'),
(802, 'Pemeriksaan Mutu Ekonomi Negara', 8, 'Masuki peranan inspektor kilang yang memeriksa mutu ekonomi negara dengan borang dan cop LULUS. Kau mengenali industri petroleum dan gas, automotif dan pelancongan yang menjana pendapatan negara.'),
(803, 'Kedai Jenama Malaysia: Cerita Setiap Rak', 8, 'Masuki peranan pemilik kedai jenama Malaysia yang menceritakan kisah di sebalik setiap rak. Kau mengenali barangan buatan Malaysia, pencapaian pembangunan, perhubungan dan perdagangan serta kepentingan kemajuan ekonomi.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e8_n1_s1', 'Sawah kecil di tepi kampung. Pak Tani Dahulu menolak tawaran mesin kerana katanya cara lama sudah cukup. Kau perlu menunjukkan ciri ekonomi tradisional yang dia amalkan.', 1, 801, 'ekonomi_tradisional.png'),
('e8_n1_s2', 'Ladang besar bersebelahan. Petani Moden menunjukkan mesin penuai kepada Pak Tani. Mereka berbalah tentang perbezaan dua cara bercucuk tanam itu.', 2, 801, 'ekonomi_komersial.png'),
('e8_n1_s3', 'Pekan lama di pedalaman. Dua gambar perlombongan terselit di buku catatan, iaitu seorang lelaki sedang mendulang dan sebuah kapal korek besar di lombong emas Sungai Lebir. Gambar-gambar itu bercampur.', 3, 801, 'kampung_dan_pedalaman.png'),
('e8_n1_s4', 'Ladang getah dan kelapa sawit bersempadan. Penoreh Getah dan Petani Moden berselisih tentang industri mana yang bermula dahulu dan sejak bila.', 4, 801, 'ladang.png'),
('e8_n1_s5', 'Kilang pemprosesan getah dan sawit. Papan buih tentang lima manfaat industri tergantung di dinding, tetapi kad-kadnya jatuh ke lantai.', 5, 801, 'industri_getah_dan_kepala_sawit.png'),
('e8_n1_s6', 'Rak produk di kilang. Seorang pelawat bertanya apa maksud industri hiliran dan biodiesel dalam kad penerangan yang tertinggal di meja.', 6, 801, 'industri_getah_dan_kepala_sawit.png'),
('e8_n1_s7', 'Hasil dieksport menunggu di kotak. Label kotak sudah luntur dan penghantar tidak pasti apa isi dalam setiap kotak getah dan sawit.', 7, 801, 'kampung_dan_pedalaman.png'),
('e8_n1_s8', 'Ladang pada waktu senja. Kau menyiapkan ringkasan perubahan dan kesinambungan ekonomi untuk diserahkan kepada pengurus ladang.', 8, 801, 'ladang.png'),
('e8_n2_s1', 'Pejabat PETRONAS di Miri. Borang tarikh sejarah industri petroleum tersilap. Jurutera pelantar minyak menolak cop LULUS sehingga kau memperbetulkannya.', 1, 802, 'industri_petroleum_dan_gas.png'),
('e8_n2_s2', 'Papan pelaporan sumbangan industri petroleum. Lima kad sumbangan ada, tetapi pengurus kilang tidak tahu yang mana benar.', 2, 802, 'industri_petroleum_dan_gas.png'),
('e8_n2_s3', 'Litar permotoran. Penonton bersorak. Seorang wartawan bertanya mengapa syarikat minyak negara menaja sukan, bukan hanya mengeluarkan minyak.', 3, 802, 'sukan_permotoran.png'),
('e8_n2_s4', 'Kilang kereta nasional. Papan putih di pejabat inspektor mempunyai lima tarikh penting industri automotif yang bercampur. Penyelia kilang menunggu laporan.', 4, 802, 'industri_automotif.png'),
('e8_n2_s5', 'Pameran model kereta di kilang. Pengunjung keliru antara PROTON dan PERODUA. Beberapa kad butiran bertukar tempat.', 5, 802, 'industri_automotif.png'),
('e8_n2_s6', 'Jabatan pelancongan. Kempen Tahun Melawat Malaysia sedang dikaji. Papan promosi mahu empat bukti keistimewaan alam semula jadi yang menarik pelancong.', 6, 802, 'industri_pelancongan.png'),
('e8_n2_s7', 'Papan keistimewaan pelancongan tergantung di pejabat. Lima kad keistimewaan terpisah daripada kategorinya. Seorang pegawai mahu semuanya dipadankan sebelum mesyuarat.', 7, 802, 'industri_pelancongan.png'),
('e8_n2_s8', 'Litar antarabangsa pada hari perlumbaan. Pegawai pelancongan bertanya kegiatan antarabangsa mana yang dianjurkan di Malaysia dan di mana, kerana senarai itu bercampur.', 8, 802, 'formula_one_formula_e.png'),
('e8_n3_s1', 'Pintu kedai dibuka. Pelanggan lama menunjuk poster Kempen Beli Barangan Buatan Malaysia dan bertanya bila kempen itu dilancarkan.', 1, 803, 'barangan_buatan_malaysia.png'),
('e8_n3_s2', 'Rak berlabel Pertanian, Petroleum dan Automotif. Pelanggan mengambil tiga produk tetapi tersalah meletakkannya kembali. Kau perlu membetulkan susunan.', 2, 803, 'barangan_buatan_malaysia.png'),
('e8_n3_s3', 'Di luar kedai, pemandangan bandar penuh bangunan tinggi dan jaringan jalan raya. Pelanggan muda bertanya apakah bukti kemakmuran negara yang boleh dilihat.', 3, 803, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e8_n3_s4', 'Papan putih kedai. Pelanggan bertanya apakah tiga pencapaian pesat ekonomi dan apa maksud setiap satu. Kad-kad penerangan bercampur.', 4, 803, 'malaysia_dan_dunia_serantau.png'),
('e8_n3_s5', 'Sesi soal jawab pelanggan. Seorang remaja bertanya mengapa dia perlu bangga dengan barangan buatan Malaysia. Kad jawapan bertaburan di atas kaunter.', 5, 803, 'barangan_buatan_malaysia.png'),
('e8_n3_s6', 'Malam sebelum kedai ditutup. Kau membaca borang soal selidik pelanggan tentang kepentingan kemajuan ekonomi. Lapan pernyataan perlu ditanda benar atau salah, tetapi hanya satu kad betul ada di atas meja.', 6, 803, 'ladang.png'),
('e8_n3_s7', 'Kedai menutup pintu. Cikgu datang menyemak projek kedai sekolah. Dia bertanya apa peranan diri, masyarakat dan negara dalam menyokong ekonomi.', 7, 803, 'kampung_dan_pedalaman.png'),
('e8_n3_s8', 'Papan imbas kembali Unit 8 tergantung di dinding kedai. Pelanggan terakhir mahu rumusan, iaitu apa perbezaan ekonomi tradisional dan komersial, dan industri mana yang memacu kemajuan?', 8, 803, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(801, 'e8_n1_s1', 'Cari Bukti Ekonomi Tradisional', 'Cari empat bukti ekonomi tradisional dalam sektor pertanian.', '2', 'Mengenal pasti ciri ekonomi tradisional: skala kecil, peralatan mudah (cangkul, sabit), modal kecil, tenaga kerja sedikit, untuk keperluan sendiri dan keluarga.', '{"bgImage": "../assets/gameAsset/background/ekonomi_tradisional.png", "hotspots": [{"name": "Cangkul di tepi petak: peralatan mudah ekonomi tradisional", "top": "78%", "left": "13.7%"}, {"name": "Cangkul kedua di tepi pagar: modal kecil dan alat sederhana", "top": "75%", "left": "86%"}, {"name": "Rumah kayu petani: hasil untuk keperluan sendiri dan keluarga", "top": "20.8%", "left": "22.4%"}, {"name": "Petak sawah kecil: dijalankan secara kecil-kecilan", "top": "39.3%", "left": "59.9%"}], "aftermath": "Bukti tidak ditemui dan Pak Tani menyangka kau mengejek caranya.", "turns": [{"after": 6, "options": [{"text": "Cara ini sesuai untuk keperluan sendiri dan keluarga.", "isCorrect": true, "reaction": "Betul. Itulah maksud ekonomi tradisional."}, {"text": "Bagi aku, cara ini hanya untuk dijual ke luar negara.", "isCorrect": false, "reaction": "Pak Tani membetulkan. Hasilnya untuk keluarga sendiri."}, {"text": "Cara ini memerlukan modal yang sangat besar, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Gambar menunjukkan alat mudah dan modal kecil."}], "clue": "Tradisional: kecil dan untuk keluarga."}]}'),
(802, 'e8_n1_s2', 'Tradisional dan Komersial', 'Padankan ciri dengan jenis ekonominya.', '4', 'Membezakan ekonomi tradisional (kecil-kecilan, alat mudah, modal kecil, keperluan sendiri) dengan komersial (perladangan, mesin dan jentera, modal besar, tenaga buruh banyak, tempatan dan eksport).', '{"pairs": [{"text": "Ekonomi tradisional: skala usaha", "pair": 1}, {"text": "Diusahakan secara kecil-kecilan", "pair": 1}, {"text": "Ekonomi tradisional: tujuan", "pair": 2}, {"text": "Untuk keperluan sendiri dan keluarga", "pair": 2}, {"text": "Ekonomi komersial: skala usaha", "pair": 3}, {"text": "Diusahakan secara perladangan", "pair": 3}, {"text": "Ekonomi komersial: peralatan", "pair": 4}, {"text": "Mesin dan jentera penuai", "pair": 4}, {"text": "Ekonomi komersial: modal dan tenaga kerja", "pair": 5}, {"text": "Modal besar dan tenaga buruh yang banyak", "pair": 5}, {"text": "Ekonomi komersial: tujuan", "pair": 6}, {"text": "Kegunaan tempatan dan eksport", "pair": 6}], "aftermath": "Ciri bertukar dan Pak Tani menyangka mesin hanya boleh dibeli oleh orang kaya. Dia pulang kecewa.", "turns": [{"after": 6, "options": [{"text": "Cara berubah mengikut zaman, tetapi kedua-duanya menyumbang kepada negara.", "isCorrect": true, "reaction": "Betul. Pak Tani mengangguk."}, {"text": "Aku fikir cara tradisional salah dan mesti dihapuskan, kerana itu lebih senang.", "isCorrect": false, "reaction": "Pak Tani terguris kerana cara itu memberi makan keluarganya."}, {"text": "Cara komersial tidak memberi manfaat kepada negara, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Petani Moden membantah kerana ia menyumbang kepada pendapatan negara."}], "clue": "Kedua-duanya menyumbang kepada negara."}]}'),
(803, 'e8_n1_s3', 'Nota Perlombongan', 'Baca nota dan tentukan kaedah perlombongan tradisional.', '5', 'Memahami perlombongan: tradisional menggunakan kaedah mendulang; komersial menggunakan kapal korek (lombong emas Sungai Lebir, Kelantan); ekonomi komersial menggalakkan pembukaan bandar di kawasan perlombongan.', '{"clueText": "Nota: Aktiviti melombong secara tradisional menggunakan kaedah mendulang. Aktiviti perlombongan secara komersial pula menggunakan jentera seperti kapal korek, contohnya di lombong emas Sungai Lebir, Kelantan. Pengenalan ekonomi komersial menggalakkan pembukaan bandar-bandar di kawasan perlombongan.", "options": [{"text": "Tradisional: mendulang. Komersial: kapal korek.", "isCorrect": true}, {"text": "Tradisional: kapal korek. Komersial: mendulang.", "isCorrect": false, "consequence": "Kedua-duanya terbalik. Nota menyebut sebaliknya."}, {"text": "Kedua-duanya menggunakan kapal korek.", "isCorrect": false, "consequence": "Mendulang ialah kaedah tradisional."}, {"text": "Kedua-duanya menggunakan mendulang.", "isCorrect": false, "consequence": "Kapal korek digunakan dalam perlombongan komersial."}], "aftermath": "Nota tersalah baca dan buku catatan menyatakan mendulang kaedah moden. Pembaca keliru.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, ekonomi komersial membawa kemajuan dan menggalakkan pembukaan bandar.", "isCorrect": true, "reaction": "Betul. Itulah perubahan yang baik."}, {"text": "Ekonomi komersial menutup semua bandar, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Nota menyebut sebaliknya. Bandar dibuka di kawasan perlombongan."}, {"text": "Sebenarnya, kapal korek hanya digunakan oleh penduduk kampung untuk mandi.", "isCorrect": false, "reaction": "Kapal korek digunakan untuk melombong."}], "clue": "Komersial menggalakkan pembukaan bandar."}]}'),
(804, 'e8_n1_s4', 'Nota Getah dan Sawit', 'Baca nota dan tentukan tempoh industri getah dan kelapa sawit bermula.', '5', 'Memahami bahawa industri getah dan kelapa sawit bermula sejak awal abad ke-20 dan merupakan sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.', '{"clueText": "Nota: Industri getah dan kelapa sawit yang bermula sejak awal abad ke-20 merupakan sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.", "options": [{"text": "Sejak awal abad ke-20.", "isCorrect": true}, {"text": "Sejak zaman Kesultanan Melayu Melaka.", "isCorrect": false, "consequence": "Nota menyebut awal abad ke-20."}, {"text": "Selepas tahun 1990.", "isCorrect": false, "consequence": "Nota menyebut awal abad ke-20."}, {"text": "Sejak tahun 1957.", "isCorrect": false, "consequence": "Nota menyebut awal abad ke-20, bukan 1957."}], "aftermath": "Nota tersalah baca dan penoreh menyangka sawit bermula selepas merdeka.", "turns": [{"after": 5, "options": [{"text": "Industri itu merangsang kemajuan ekonomi negara sejak lama.", "isCorrect": true, "reaction": "Betul. Itulah asas perladangan kita."}, {"text": "Industri itu baru bermula dan tidak penting, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Penoreh membantah. Ia menyumbang sejak awal abad ke-20."}, {"text": "Aku fikir industri itu tidak berkaitan dengan ekonomi.", "isCorrect": false, "reaction": "Penoreh menggeleng kerana ia merangsang kemajuan ekonomi."}], "clue": "Getah dan sawit: pemacu lama."}]}'),
(805, 'e8_n1_s5', 'Lima Manfaat Getah dan Sawit', 'Padankan manfaat industri getah dan kelapa sawit dengan penerangannya.', '4', 'Memahami lima sumbangan: meningkatkan pendapatan negara, menyediakan peluang pekerjaan, mewujudkan industri hiliran, memajukan industri asas tani, membangunkan industri biodiesel.', '{"pairs": [{"text": "Meningkatkan pendapatan negara", "pair": 1}, {"text": "Hasil getah dan sawit dieksport, seperti sarung tangan dan minyak", "pair": 1}, {"text": "Menyediakan peluang pekerjaan", "pair": 2}, {"text": "Perladangan memerlukan tenaga kerja yang banyak", "pair": 2}, {"text": "Mewujudkan industri hiliran", "pair": 3}, {"text": "Contohnya pembuatan perabot daripada kayu getah", "pair": 3}, {"text": "Memajukan industri asas tani", "pair": 4}, {"text": "Meningkatkan pengeluaran bahan makanan tempatan", "pair": 4}, {"text": "Membangunkan industri biodiesel", "pair": 5}, {"text": "Sawit diproses menjadi biodiesel, minyak dan sabun", "pair": 5}], "aftermath": "Kad bertukar dan kilang menyatakan getah tidak memberi peluang pekerjaan. Penoreh terkilan.", "turns": [{"after": 7, "options": [{"text": "Pada pendapat aku, industri itu memberi pekerjaan dan menjana pendapatan kepada rakyat.", "isCorrect": true, "reaction": "Betul. Kerja kau berfaedah."}, {"text": "Aku fikir industri itu hanya memberi keuntungan kepada pemilik ladang, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Penduduk membantah kerana banyak peluang pekerjaan disediakan."}, {"text": "Industri itu tidak menghasilkan produk selain getah, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Sawit menghasilkan minyak, sabun dan biodiesel."}], "clue": "Industri memberi kerja dan pendapatan."}]}'),
(806, 'e8_n1_s6', 'Nota Hiliran dan Biodiesel', 'Baca nota dan tentukan maksud industri hiliran.', '5', 'Memahami industri hiliran: kegiatan yang berkembang daripada kegiatan ekonomi utama, contohnya pembuatan perabot daripada kayu getah; biodiesel: bahan buangan organik yang digunakan sebagai bahan api.', '{"clueText": "Nota: Industri hiliran bermaksud kegiatan yang berkembang daripada kegiatan ekonomi utama. Contohnya, pembuatan perabot daripada kayu getah. Biodiesel pula bermaksud bahan buangan organik yang digunakan sebagai bahan api, dan industri kelapa sawit turut menghasilkan biodiesel sawit.", "options": [{"text": "Kegiatan yang berkembang daripada kegiatan ekonomi utama.", "isCorrect": true}, {"text": "Kegiatan menanam padi secara kecil-kecilan.", "isCorrect": false, "consequence": "Itu ciri ekonomi tradisional."}, {"text": "Kegiatan menjual barangan melalui Internet.", "isCorrect": false, "consequence": "Itu e-dagang."}, {"text": "Kegiatan mendulang bijih timah di sungai.", "isCorrect": false, "consequence": "Itu kaedah perlombongan tradisional."}], "aftermath": "Nota tersalah baca dan pelawat menyangka industri hiliran ialah kerja menanam. Pelawat pulang keliru.", "turns": [{"after": 5, "options": [{"text": "Aku fikir industri hiliran menambah pendapatan negara menerusi pasaran tempatan dan antarabangsa.", "isCorrect": true, "reaction": "Betul. Pelawat tersenyum."}, {"text": "Sebenarnya, industri hiliran hanya membazir kayu, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Industri hiliran menyumbang kepada pendapatan negara."}, {"text": "Industri hiliran tiada kaitan dengan getah, kerana tiada siapa yang akan peduli dan lupakan sahaja.", "isCorrect": false, "reaction": "Perabot daripada kayu getah ialah contoh."}], "clue": "Hiliran menambah pendapatan negara."}]}'),
(807, 'e8_n1_s7', 'Hasil Eksport Getah dan Sawit', 'Padankan hasil eksport dengan industri sumbernya.', '4', 'Memahami hasil eksport: getah (sarung tangan, benang lateks); kelapa sawit (minyak mentah, minyak yang telah diproses, sabun).', '{"pairs": [{"text": "Sarung tangan", "pair": 1}, {"text": "Barangan getah yang dieksport dan dipakai untuk melindungi tangan", "pair": 1}, {"text": "Benang lateks", "pair": 2}, {"text": "Hasil getah yang dieksport untuk membuat barangan kenyal", "pair": 2}, {"text": "Minyak mentah sawit", "pair": 3}, {"text": "Hasil kelapa sawit sebelum diproses", "pair": 3}, {"text": "Minyak sawit diproses", "pair": 4}, {"text": "Hasil kelapa sawit selepas diproses untuk dieksport", "pair": 4}, {"text": "Sabun", "pair": 5}, {"text": "Produk yang diproses daripada kelapa sawit", "pair": 5}], "aftermath": "Label tersilap dan kotak dihantar ke destinasi yang salah. Penghantar mengeluh.", "turns": [{"after": 6, "options": [{"text": "Aku fikir hasil eksport meningkatkan pendapatan negara.", "isCorrect": true, "reaction": "Betul. Kotak dihantar dengan tepat."}, {"text": "Hasil eksport tidak memberi apa-apa kepada negara.", "isCorrect": false, "reaction": "Penghantar menggeleng. Eksport meningkatkan pendapatan."}, {"text": "Hasil eksport hanya untuk kegunaan keluarga petani.", "isCorrect": false, "reaction": "Itu ciri ekonomi tradisional, bukan eksport."}], "clue": "Eksport meningkatkan pendapatan."}]}'),
(808, 'e8_n1_s8', 'Peringkat Perkembangan Ekonomi', 'Susun peringkat perkembangan ekonomi dan kegiatan pemacu kemajuan negara.', '1', 'Merumus perkembangan: ekonomi tradisional (pertanian dan perlombongan) -> ekonomi komersial -> industri getah dan kelapa sawit -> petroleum (1910) -> PETRONAS (1974) -> PROTON (1983).', '{"timelineItems": [{"id": 1, "year": "Zaman awal", "text": "Pertanian dan perlombongan tradisional diusahakan kecil-kecilan", "why": "Kegiatan awal ekonomi negara."}, {"id": 2, "year": "Awal abad ke-20", "text": "Industri getah dan kelapa sawit berkembang secara perladangan", "why": "Ekonomi komersial menggalakkan perladangan."}, {"id": 3, "year": "1910", "text": "Industri petroleum bermula di Miri, Sarawak", "why": "Telaga pertama di Miri."}, {"id": 4, "year": "1974", "text": "PETRONAS ditubuhkan dan dimiliki sepenuhnya oleh kerajaan", "why": "Memajukan industri petroleum dan gas."}, {"id": 5, "year": "1983", "text": "PROTON ditubuhkan di Shah Alam, Selangor", "why": "Industri automotif negara bermula."}], "aftermath": "Susunan tersalah dan ringkasan menyatakan PROTON mendahului getah. Pengurus ladang menggeleng.", "turns": [{"after": 6, "options": [{"text": "Kemajuan ekonomi bermula daripada pertanian dan berkembang ke pelbagai sektor.", "isCorrect": true, "reaction": "Betul. Pengurus mengangguk."}, {"text": "Ekonomi negara sentiasa bergantung pada getah sahaja, kerana itu lebih senang.", "isCorrect": false, "reaction": "Pengurus membetulkan. Banyak industri baharu muncul."}, {"text": "Ekonomi negara tidak pernah berubah, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Ekonomi berkembang daripada tradisional ke komersial."}], "clue": "Ekonomi berkembang berperingkat."}]}'),
(809, 'e8_n2_s1', 'Nota Sejarah Petroleum', 'Baca nota dan tentukan permulaan industri petroleum dan penubuhan PETRONAS.', '5', 'Memahami petroleum: bermula tahun 1910 di Miri, Sarawak; PETRONAS ditubuhkan tahun 1974 dan dimiliki sepenuhnya oleh kerajaan Malaysia; telaga minyak pertama The Grand Old Lady, Miri.', '{"clueText": "Nota: Industri petroleum di negara kita bermula pada tahun 1910 di Miri, Sarawak. Petroliam Nasional Berhad (PETRONAS) yang dimiliki sepenuhnya oleh kerajaan Malaysia ditubuhkan pada tahun 1974. The Grand Old Lady, Miri merupakan telaga minyak yang pertama di negara kita.", "options": [{"text": "Bermula 1910 di Miri dan PETRONAS ditubuhkan 1974.", "isCorrect": true}, {"text": "Bermula 1974 di Miri dan PETRONAS ditubuhkan 1910.", "isCorrect": false, "consequence": "Tahun terbalik. Nota menyebut sebaliknya."}, {"text": "Bermula 1983 di Shah Alam dan PETRONAS ditubuhkan 1985.", "isCorrect": false, "consequence": "Itu tarikh industri automotif."}, {"text": "Bermula 1957 di Kuala Lumpur dan PETRONAS ditubuhkan 1963.", "isCorrect": false, "consequence": "Tarikh itu tidak betul."}], "aftermath": "Borang diluluskan dengan tarikh salah dan laporan petroleum memuatkan fakta cacat.", "turns": [{"after": 6, "options": [{"text": "Penubuhan PETRONAS memajukan industri petroleum dan gas negara.", "isCorrect": true, "reaction": "Betul. Cop LULUS diberikan."}, {"text": "PETRONAS dimiliki oleh syarikat luar negara, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Nota menyebut PETRONAS dimiliki sepenuhnya oleh kerajaan Malaysia."}, {"text": "PETRONAS tiada kaitan dengan petroleum, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Jurutera menggeleng. PETRONAS memajukan industri itu."}], "clue": "PETRONAS dimiliki kerajaan."}]}'),
(810, 'e8_n2_s2', 'Sumbangan Industri Petroleum', 'Padankan sumbangan industri petroleum dan gas dengan penerangannya.', '4', 'Memahami sumbangan petroleum: peluang pekerjaan (pelantar minyak), melahirkan usahawan (stesen minyak), penaja sukan permotoran (Grand Prix), biasiswa (Universiti Teknologi PETRONAS), pulangan pendapatan tinggi.', '{"pairs": [{"text": "Peluang pekerjaan", "pair": 1}, {"text": "Pekerja di pelantar minyak dan pusat pemprosesan", "pair": 1}, {"text": "Melahirkan usahawan", "pair": 2}, {"text": "Pembukaan stesen minyak", "pair": 2}, {"text": "Penaja utama sukan permotoran", "pair": 3}, {"text": "Grand Prix Malaysia meningkatkan pendapatan negara", "pair": 3}, {"text": "Biasiswa pelajaran", "pair": 4}, {"text": "Melanjutkan pelajaran ke Universiti Teknologi PETRONAS", "pair": 4}, {"text": "Pulangan pendapatan tinggi", "pair": 5}, {"text": "Hasil daripada permintaan tinggi dunia terhadap petroleum", "pair": 5}], "aftermath": "Kad bertukar dan laporan menyatakan petroleum tidak melahirkan usahawan. Jurutera menegur.", "turns": [{"after": 6, "options": [{"text": "Industri petroleum penting dan wajar dibanggakan.", "isCorrect": true, "reaction": "Betul. Cop LULUS diberikan."}, {"text": "Menurut aku, industri petroleum tidak penting kepada negara.", "isCorrect": false, "reaction": "Jurutera membantah. Ia penjana kemajuan ekonomi."}, {"text": "Menurut aku, industri petroleum hanya memberi kerja kepada orang asing.", "isCorrect": false, "reaction": "Penduduk tempatan menikmati peluang pekerjaan."}], "clue": "Petroleum penjana ekonomi."}]}'),
(811, 'e8_n2_s3', 'Nota Penajaan Sukan Permotoran', 'Baca nota dan tentukan sebab PETRONAS menaja sukan permotoran.', '5', 'Memahami bahawa PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia dan penganjuran sukan ini meningkatkan pendapatan negara.', '{"clueText": "Nota: PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia. Penganjuran sukan ini meningkatkan pendapatan negara.", "options": [{"text": "Penganjuran sukan permotoran meningkatkan pendapatan negara.", "isCorrect": true}, {"text": "Sukan permotoran menggantikan industri petroleum.", "isCorrect": false, "consequence": "Nota tidak menyatakan begitu."}, {"text": "Sukan permotoran dianjurkan untuk menutup pelantar minyak.", "isCorrect": false, "consequence": "Tiada maklumat itu dalam nota."}, {"text": "Sukan permotoran hanya hiburan tanpa sebarang kesan.", "isCorrect": false, "consequence": "Nota menyatakan ia meningkatkan pendapatan negara."}], "aftermath": "Nota tersalah baca dan wartawan menulis penajaan itu membazir wang.", "turns": [{"after": 6, "options": [{"text": "Penajaan sukan memberi manfaat kepada negara dan rakyat.", "isCorrect": true, "reaction": "Betul. Wartawan menulis laporan baharu."}, {"text": "Sebenarnya, penajaan sukan hanya membazir wang, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Nota menyatakan ia meningkatkan pendapatan negara."}, {"text": "Penajaan sukan tiada kaitan dengan pendapatan.", "isCorrect": false, "reaction": "Penganjuran sukan meningkatkan pendapatan negara."}], "clue": "Sukan menambah pendapatan."}]}'),
(812, 'e8_n2_s4', 'Garis Masa Industri Automotif', 'Susun peristiwa penting industri automotif mengikut urutan.', '1', 'Menyusun kronologi: PROTON 1983, Proton Saga Julai 1985, PERODUA 1993, Kancil 1994, kilang kedua PROTON di Tanjung Malim 2005, kerjasama Geely 2018.', '{"timelineItems": [{"id": 1, "year": "1983", "text": "PROTON ditubuhkan di Shah Alam, Selangor", "why": "Kilang pembuatan kereta nasional yang pertama."}, {"id": 2, "year": "Julai 1985", "text": "Proton Saga dilancarkan sebagai model kereta pertama negara", "why": "Menjadi pengeluar kereta pertama di Malaysia."}, {"id": 3, "year": "1993", "text": "PERODUA ditubuhkan", "why": "Perusahaan Otomobil Kedua Sdn. Bhd."}, {"id": 4, "year": "1994", "text": "Model pertama PERODUA, Kancil, dikeluarkan", "why": "Selepas PERODUA ditubuhkan."}, {"id": 5, "year": "2005", "text": "Kilang kedua PROTON dibina di Tanjung Malim, Perak", "why": "Kilang kedua selepas Shah Alam."}, {"id": 6, "year": "2018", "text": "PROTON menjalin usaha sama dengan Geely Holding Group", "why": "Untuk mengeluarkan model baharu."}], "aftermath": "Susunan tersilap dan laporan menyatakan Kancil dikeluarkan sebelum PERODUA ditubuhkan.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, pencapaian ini membanggakan negara.", "isCorrect": true, "reaction": "Betul. Kilang menyambut laporan itu."}, {"text": "Sebenarnya, industri automotif tiada kesan kepada ekonomi.", "isCorrect": false, "reaction": "Penyelia menggeleng. Pendapatan negara tidak lagi bergantung pada pertanian sahaja."}, {"text": "Semua kereta di Malaysia diimport sepenuhnya.", "isCorrect": false, "reaction": "PROTON dan PERODUA ialah pengeluar tempatan."}], "clue": "Automotif membanggakan negara."}]}'),
(813, 'e8_n2_s5', 'PROTON dan PERODUA', 'Padankan syarikat automotif dengan butirannya.', '4', 'Memahami PROTON (Shah Alam 1983; Saga Julai 1985; kilang kedua Tanjung Malim 2005; Geely 2018) dan PERODUA (1993; Kancil 1994; Nippa dieksport ke United Kingdom).', '{"pairs": [{"text": "PROTON ditubuhkan", "pair": 1}, {"text": "Kilang pertama di Shah Alam pada tahun 1983", "pair": 1}, {"text": "Proton Saga", "pair": 2}, {"text": "Model kereta pertama negara pada Julai 1985", "pair": 2}, {"text": "Kilang kedua PROTON", "pair": 3}, {"text": "Tanjung Malim, Perak pada tahun 2005", "pair": 3}, {"text": "PERODUA ditubuhkan", "pair": 4}, {"text": "Tahun 1993", "pair": 4}, {"text": "Kancil", "pair": 5}, {"text": "Model pertama PERODUA pada tahun 1994", "pair": 5}, {"text": "Nippa", "pair": 6}, {"text": "Produk PERODUA yang dieksport ke United Kingdom", "pair": 6}], "aftermath": "Butiran bertukar dan pengunjung mencatat Kancil sebagai model PROTON.", "turns": [{"after": 6, "options": [{"text": "Industri ini mendorong perkembangan industri berat dan teknologi.", "isCorrect": true, "reaction": "Betul. Pengunjung terkesan."}, {"text": "Pada pendapat aku, industri ini menyebabkan pendapatan negara menurun.", "isCorrect": false, "reaction": "Industri automotif meningkatkan ekonomi negara."}, {"text": "Rasanya, industri ini menghentikan kemajuan teknologi.", "isCorrect": false, "reaction": "Ia mendorong perkembangan industri berat dan teknologi."}], "clue": "Automotif mendorong teknologi."}]}'),
(814, 'e8_n2_s6', 'Cari Bukti Alam Semula Jadi', 'Cari empat bukti keindahan alam semula jadi yang menarik pelancong.', '2', 'Memahami keistimewaan Malaysia: keindahan alam semula jadi (flora, fauna, pulau, laut, tanah tinggi) menarik pelancong dan Kempen Tahun Melawat Malaysia sejak tahun 1990.', '{"bgImage": "../assets/gameAsset/background/industri_pelancongan.png", "hotspots": [{"name": "Air terjun hutan: alam semula jadi memacu Tahun Melawat Malaysia", "top": "28.3%", "left": "27.7%"}, {"name": "Pelancong di jambatan gantung: tarikan alam semula jadi", "top": "24%", "left": "5%"}, {"name": "Gua batu kapur: tapak semula jadi yang menarik pelancong", "top": "64.6%", "left": "30.1%"}, {"name": "Pelancong bergambar di pantai: Tahun Melawat Malaysia", "top": "67.8%", "left": "72.8%"}], "aftermath": "Bukti tidak ditemui dan promosi pelancongan gagal menunjukkan daya tarikan negara.", "turns": [{"after": 6, "options": [{"text": "Alam semula jadi perlu dipelihara supaya terus menarik pelancong.", "isCorrect": true, "reaction": "Betul. Pelancong gembira."}, {"text": "Bagi aku, alam semula jadi boleh dirosakkan kerana pelancong tetap datang.", "isCorrect": false, "reaction": "Itu merugikan industri pelancongan."}, {"text": "Alam semula jadi tidak menarik pelancong dan lupakan sahaja.", "isCorrect": false, "reaction": "Bukti dalam gambar menunjukkan sebaliknya."}], "clue": "Pelihara alam sebagai tarikan."}]}'),
(815, 'e8_n2_s7', 'Keistimewaan Pelancongan Malaysia', 'Padankan keistimewaan pelancongan dengan penerangannya.', '4', 'Memahami keistimewaan pelancongan: tapak dan bangunan bersejarah, keindahan alam semula jadi, keharmonian masyarakat dan keunikan budaya, agropelancongan (inap desa), penganjuran sukan, muzik dan pameran antarabangsa.', '{"pairs": [{"text": "Tapak dan bangunan bersejarah", "pair": 1}, {"text": "Kota A Famosa, Candi Bukit Batu Pahat dan Istana Kenangan", "pair": 1}, {"text": "Keindahan alam semula jadi", "pair": 2}, {"text": "Gunung Kinabalu, Pulau Langkawi dan Gua Niah", "pair": 2}, {"text": "Keharmonian dan keunikan budaya", "pair": 3}, {"text": "Hidup pelbagai kaum menjamin keselamatan dan menarik pelancong", "pair": 3}, {"text": "Agropelancongan", "pair": 4}, {"text": "Konsep inap desa bersama keluarga penduduk tempatan", "pair": 4}, {"text": "Sukan, muzik dan pameran antarabangsa", "pair": 5}, {"text": "Formula One, Le Tour de Langkawi, Festival Muzik Hutan Hujan dan LIMA", "pair": 5}], "aftermath": "Kad bertukar dan pegawai membentangkan keistimewaan yang salah dalam mesyuarat.", "turns": [{"after": 7, "options": [{"text": "Keharmonian masyarakat juga menjadi tarikan pelancong.", "isCorrect": true, "reaction": "Betul. Pegawai mencatat idea itu."}, {"text": "Keharmonian tidak mempengaruhi pelancong, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Pegawai membetulkan. Keharmonian menjamin keselamatan pelancong."}, {"text": "Hanya bangunan lama yang menarik pelancong.", "isCorrect": false, "reaction": "Alam dan budaya juga menarik pelancong."}], "clue": "Keharmonian menarik pelancong."}]}'),
(816, 'e8_n2_s8', 'Acara Antarabangsa di Malaysia', 'Padankan acara antarabangsa dengan tempat atau cirinya.', '4', 'Memahami acara: Formula One di Sepang; Le Tour de Langkawi; Festival Muzik Hutan Hujan Sedunia di Sarawak; LIMA (pameran maritim dan aeroangkasa) di Pulau Langkawi setiap dua tahun.', '{"pairs": [{"text": "Perlumbaan Formula One", "pair": 1}, {"text": "Dianjurkan di Sepang", "pair": 1}, {"text": "Le Tour de Langkawi", "pair": 2}, {"text": "Perlumbaan basikal antarabangsa", "pair": 2}, {"text": "Festival Muzik Hutan Hujan Sedunia", "pair": 3}, {"text": "Dianjurkan di Sarawak", "pair": 3}, {"text": "LIMA", "pair": 4}, {"text": "Pameran maritim dan aeroangkasa di Pulau Langkawi setiap dua tahun", "pair": 4}], "aftermath": "Peristiwa bertukar tempat dan senarai acara tersalah dicetak. Pegawai terpaksa mencetak semula.", "turns": [{"after": 5, "options": [{"text": "Rasanya, acara antarabangsa menarik pelancong dan meningkatkan pendapatan negara.", "isCorrect": true, "reaction": "Betul. Pelancong gembira."}, {"text": "Acara antarabangsa hanya menyusahkan penduduk, lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Pegawai menggeleng. Acara itu mempromosikan negara."}, {"text": "Aku fikir acara antarabangsa tiada kesan kepada ekonomi, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Ia menarik pelancong dan menambah pendapatan."}], "clue": "Acara menarik pelancong."}]}'),
(817, 'e8_n3_s1', 'Nota Kempen Beli Barangan Buatan Malaysia', 'Baca nota dan tentukan tahun kempen dilancarkan serta contoh barangan.', '5', 'Memahami bahawa Kempen ''Beli Barangan Buatan Malaysia'' dilancarkan pada tahun 1985; contoh: perabot, barangan elektrik dan elektronik, produk makanan.', '{"clueText": "Nota: Kempen ''Beli Barangan Buatan Malaysia'' dilancarkan pada tahun 1985. Antara barangan buatan Malaysia termasuklah perabot, barangan elektrik dan elektronik serta produk makanan.", "options": [{"text": "Tahun 1985; contohnya perabot, elektrik dan elektronik, makanan.", "isCorrect": true}, {"text": "Tahun 1957; contohnya hanya bijih timah.", "isCorrect": false, "consequence": "Tahun 1957 ialah tahun kemerdekaan. Nota menyebut 1985."}, {"text": "Tahun 1990; contohnya hanya kereta.", "isCorrect": false, "consequence": "Tahun 1990 ialah Kempen Tahun Melawat Malaysia."}, {"text": "Tahun 1974; contohnya hanya minyak petrol.", "isCorrect": false, "consequence": "Tahun 1974 ialah penubuhan PETRONAS."}], "aftermath": "Nota tersalah baca dan poster di kedai menulis tahun yang salah. Pelanggan menegur.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, membeli barangan tempatan menyokong ekonomi negara.", "isCorrect": true, "reaction": "Betul. Pelanggan membeli sebakul barangan."}, {"text": "Barangan buatan Malaysia kurang bermutu, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Pelanggan terkilan. Kualiti telah mencapai tahap kegunaan tempatan dan antarabangsa."}, {"text": "Barangan Malaysia hanya untuk pelancong, kerana itu lebih senang.", "isCorrect": false, "reaction": "Ia untuk kegunaan tempatan dan antarabangsa."}], "clue": "Beli barangan buatan Malaysia."}]}'),
(818, 'e8_n3_s2', 'Rak Barangan Buatan Malaysia', 'Padankan produk dengan kategori industrinya.', '4', 'Memahami produk jenama Malaysia: pertanian (minyak masak, sabun, nanas, durian), petroleum (minyak petrol, minyak pelincir kenderaan, gas memasak), automotif (kereta dan motosikal).', '{"pairs": [{"text": "Minyak masak dan sabun", "pair": 1}, {"text": "Produk pertanian daripada sawit", "pair": 1}, {"text": "Buah durian dan buah nanas", "pair": 2}, {"text": "Produk pertanian berupa buah-buahan", "pair": 2}, {"text": "Minyak petrol", "pair": 3}, {"text": "Bahan api kenderaan daripada petroleum", "pair": 3}, {"text": "Minyak pelincir kenderaan", "pair": 4}, {"text": "Produk petroleum untuk melincirkan enjin", "pair": 4}, {"text": "Gas untuk memasak", "pair": 5}, {"text": "Produk petroleum untuk kegunaan di dapur", "pair": 5}, {"text": "Kereta dan motosikal", "pair": 6}, {"text": "Produk automotif keluaran negara", "pair": 6}], "aftermath": "Rak tersusun salah dan pelanggan membeli produk yang tidak mereka perlukan. Kedai kecoh.", "turns": [{"after": 7, "options": [{"text": "Produk ini membanggakan kerana mencapai kualiti kegunaan tempatan dan antarabangsa.", "isCorrect": true, "reaction": "Betul. Kedai kembali tenang."}, {"text": "Produk ini tidak perlu dibanggakan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pelanggan terkilan. Produk ini hasil usaha rakyat."}, {"text": "Rasanya, produk ini hanya dijual di luar negara, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Produk ini untuk tempatan dan antarabangsa."}], "clue": "Banggakan produk tempatan."}]}'),
(819, 'e8_n3_s3', 'Cari Bukti Pencapaian Ekonomi', 'Cari empat bukti pencapaian pesat ekonomi negara.', '2', 'Memahami pencapaian ekonomi: pembangunan (bangunan pencakar langit), perhubungan (jaringan moden terancang) dan perdagangan (e-dagang yang semakin berkembang).', '{"bgImage": "../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png", "hotspots": [{"name": "Menara pencakar langit: pembangunan negara", "top": "25.4%", "left": "22.1%"}, {"name": "Jambatan, kereta api dan jalan raya: perhubungan moden yang terancang", "top": "62%", "left": "38%"}, {"name": "Gudang E-Dagang: perdagangan yang semakin berkembang", "top": "45%", "left": "78%"}, {"name": "Papan iklan carta menaik: e-dagang semakin berkembang", "top": "22%", "left": "90%"}], "aftermath": "Bukti tidak ditemui dan pelanggan muda menyangka negara tidak berkembang.", "turns": [{"after": 6, "options": [{"text": "Kita harus bangga dan bersyukur dengan kemakmuran yang dikongsi bersama.", "isCorrect": true, "reaction": "Betul. Pelanggan muda tersenyum."}, {"text": "Sebenarnya, kemakmuran hanya untuk orang kaya, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Pelanggan membantah. Kemakmuran dikongsi bersama."}, {"text": "Pembangunan tidak perlu dibanggakan, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Itu bukti kemakmuran negara."}], "clue": "Bangga dan bersyukur."}]}'),
(820, 'e8_n3_s4', 'Pembangunan, Perhubungan, Perdagangan', 'Padankan pencapaian ekonomi dengan penerangannya.', '4', 'Memahami: pembangunan (bangunan pencakar langit sebagai lambang kemakmuran), perhubungan (jaringan moden terancang mendorong kesinambungan pembangunan), perdagangan (e-dagang membuka peluang kepada rakyat).', '{"pairs": [{"text": "Pembangunan", "pair": 1}, {"text": "Bangunan pencakar langit sebagai lambang kemakmuran negara", "pair": 1}, {"text": "Perhubungan", "pair": 2}, {"text": "Jaringan moden terancang mendorong kesinambungan pembangunan", "pair": 2}, {"text": "Perdagangan", "pair": 3}, {"text": "Kegiatan e-dagang membuka peluang kepada rakyat", "pair": 3}, {"text": "E-dagang", "pair": 4}, {"text": "Proses menjalankan urusan perniagaan melalui rangkaian Internet", "pair": 4}], "aftermath": "Kad bertukar dan e-dagang diterangkan sebagai jaringan jalan raya. Pelanggan keliru.", "turns": [{"after": 5, "options": [{"text": "E-dagang membuka peluang kepada rakyat untuk menyumbang kepada ekonomi.", "isCorrect": true, "reaction": "Betul. Pelanggan mula berniaga."}, {"text": "Pada pendapat aku, e-dagang mengurangkan peluang berniaga, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Itu salah. E-dagang membuka peluang."}, {"text": "E-dagang hanya untuk kedai besar, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Rakyat biasa juga boleh berniaga secara dalam talian."}], "clue": "E-dagang membuka peluang."}]}'),
(821, 'e8_n3_s5', 'Kad Rasa Bangga Barangan Tempatan', 'Baca kad dan tentukan kepentingan rasa bangga terhadap barangan buatan Malaysia.', '5', 'Memahami kepentingan: memajukan sistem ekonomi, memperluaskan pasaran produk tempatan, melahirkan rasa bangga, memperkenalkan identiti negara, meningkatkan produktiviti usahawan, memupuk rasa bangga.', '{"clueText": "Kad: Rasa bangga terhadap barangan buatan Malaysia memajukan sistem ekonomi negara, memperluaskan pasaran produk tempatan, memperkenalkan identiti negara dan membantu usahawan meningkatkan produktiviti.", "options": [{"text": "Memajukan ekonomi, memperluaskan pasaran tempatan dan memperkenalkan identiti negara.", "isCorrect": true}, {"text": "Melemahkan pasaran produk tempatan.", "isCorrect": false, "consequence": "Kad menyatakan ia memperluaskan pasaran tempatan."}, {"text": "Menurunkan produktiviti usahawan.", "isCorrect": false, "consequence": "Kad menyatakan usahawan meningkatkan produktiviti."}, {"text": "Menyembunyikan identiti negara.", "isCorrect": false, "consequence": "Kad menyatakan ia memperkenalkan identiti negara."}], "aftermath": "Kad tersalah baca dan remaja memilih barangan luar kerana menyangka produk tempatan tidak bermanfaat.", "turns": [{"after": 5, "options": [{"text": "Aku akan memilih produk tempatan kerana ia memajukan ekonomi negara.", "isCorrect": true, "reaction": "Betul. Remaja itu membeli beg buatan Malaysia."}, {"text": "Rasanya, aku akan memilih produk luar sahaja, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Produk tempatan ialah identiti negara."}, {"text": "Pada pendapat aku, produk tempatan tidak perlu disokong, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Sokongan membantu usahawan meningkatkan produktiviti."}], "clue": "Sokong produk tempatan."}]}'),
(822, 'e8_n3_s6', 'Kad Kepentingan Kemajuan Ekonomi', 'Baca kad dan tentukan kepentingan kemajuan ekonomi bagi mengekalkan kemakmuran negara.', '5', 'Memahami kepentingan: meningkatkan taraf hidup melalui peluang pekerjaan, infrastruktur, inovasi, kestabilan sosial dan politik, daya saing dengan negara lain.', '{"clueText": "Kad: Kemajuan ekonomi meningkatkan taraf hidup rakyat dengan menyediakan lebih banyak peluang pekerjaan, membolehkan pelaburan dalam infrastruktur seperti jalan raya dan jambatan, menyumbang kepada kestabilan sosial dan politik serta meningkatkan daya saing negara.", "options": [{"text": "Meningkatkan taraf hidup, infrastruktur dan daya saing negara.", "isCorrect": true}, {"text": "Meningkatkan kadar kemiskinan.", "isCorrect": false, "consequence": "Kad menyatakan sebaliknya."}, {"text": "Menyebabkan kemakmuran negara terjejas.", "isCorrect": false, "consequence": "Pendapatan tinggi menyumbang kepada kemakmuran."}, {"text": "Meningkatkan masalah kewangan kerajaan.", "isCorrect": false, "consequence": "Kemajuan ekonomi tidak meningkatkan masalah itu."}], "aftermath": "Kad tersalah baca dan soal selidik menyatakan kemajuan ekonomi menambah kemiskinan.", "turns": [{"after": 6, "options": [{"text": "Kemajuan ekonomi mengekalkan kemakmuran negara.", "isCorrect": true, "reaction": "Betul. Soal selidik disiapkan."}, {"text": "Kemajuan ekonomi menambah kemiskinan.", "isCorrect": false, "reaction": "Kad menyatakan sebaliknya."}, {"text": "Sebenarnya, kemajuan ekonomi tidak berkaitan dengan taraf hidup.", "isCorrect": false, "reaction": "Ia meningkatkan taraf hidup rakyat."}], "clue": "Kemajuan ekonomi memakmurkan negara."}]}'),
(823, 'e8_n3_s7', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan peranannya dalam menyokong ekonomi.', '4', 'Memahami cinta akan negara: diri (menyokong usaha meningkatkan ekonomi), masyarakat (sokongan meningkatkan pendapatan negara), negara (pendapatan dan kemajuan ekonomi dikongsi bersama).', '{"pairs": [{"text": "Diri", "pair": 1}, {"text": "Setiap warganegara menyokong usaha meningkatkan ekonomi negara", "pair": 1}, {"text": "Masyarakat", "pair": 2}, {"text": "Sokongan dalam pembangunan ekonomi meningkatkan pendapatan negara", "pair": 2}, {"text": "Negara", "pair": 3}, {"text": "Peningkatan pendapatan dan kemajuan ekonomi dikongsi bersama", "pair": 3}], "aftermath": "Padanan tersilap dan projek sekolah mendapat markah rendah. Cikgu menggeleng.", "turns": [{"after": 7, "options": [{"text": "Kita menyokong ekonomi negara supaya kemakmuran terus dikongsi bersama.", "isCorrect": true, "reaction": "Betul. Projek mendapat markah penuh."}, {"text": "Ekonomi negara hanya urusan kerajaan, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Cikgu menggeleng. Setiap warganegara perlu terlibat."}, {"text": "Kita tidak perlu menyokong kerana kemakmuran sudah cukup dan biarkan sahaja.", "isCorrect": false, "reaction": "Sokongan menjamin ekonomi terus berkembang maju."}], "clue": "Setiap warganegara menyokong ekonomi."}]}'),
(824, 'e8_n3_s8', 'Rumusan Industri Pemacu Kemajuan', 'Padankan industri pemacu kemajuan dengan cirinya.', '4', 'Merumus kegiatan ekonomi pemacu kemajuan: getah dan kelapa sawit (awal abad ke-20), petroleum dan gas (1910, PETRONAS 1974), automotif (1983 PROTON), pelancongan (Tahun Melawat Malaysia sejak 1990).', '{"pairs": [{"text": "Getah dan kelapa sawit", "pair": 1}, {"text": "Sektor pertanian utama sejak awal abad ke-20", "pair": 1}, {"text": "Petroleum dan gas", "pair": 2}, {"text": "Bermula 1910 di Miri; PETRONAS ditubuhkan 1974", "pair": 2}, {"text": "Automotif", "pair": 3}, {"text": "PROTON ditubuhkan 1983 dan PERODUA 1993", "pair": 3}, {"text": "Pelancongan", "pair": 4}, {"text": "Kempen Tahun Melawat Malaysia sejak tahun 1990", "pair": 4}], "aftermath": "Ciri bertukar dan rumusan memberi tarikh PETRONAS kepada industri pelancongan.", "turns": [{"after": 6, "options": [{"text": "Kegiatan ekonomi yang pelbagai menjana pendapatan dan mengekalkan kemakmuran negara.", "isCorrect": true, "reaction": "Betul. Kedai ditutup dengan rasa bangga."}, {"text": "Aku fikir pendapatan negara bergantung pada satu industri sahaja, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Pelbagai industri menyumbang kepada pendapatan negara."}, {"text": "Industri baharu tidak membantu negara, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Industri baharu meningkatkan ekonomi negara."}], "clue": "Pelbagai industri memacu kemajuan."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e8_n1_s1', 'hint', 'Ekonomi tradisional diusahakan kecil-kecilan dengan peralatan mudah dan modal kecil.', NULL, NULL),
(801, NULL, 'hint', 'Empat bukti. Dua cangkul, rumah kayu petani dan petak sawah kecil.', 'Di tepi sawah aku menjumpai empat bukti ekonomi tradisional. Dua cangkul yang bermodal kecil dan beralat mudah, rumah kayu petani yang mengambil hasil untuk keperluan sendiri dan keluarga, dan petak sawah kecil yang diusahakan secara kecil-kecilan.', 'Mata yang tajam! Pak Tani Dahulu mengangguk sambil menggenggam cangkulnya dengan bangga.'),
(NULL, 'e8_n1_s2', 'hint', 'Ekonomi komersial menggunakan mesin dan jentera penuai.', NULL, NULL),
(802, NULL, 'hint', 'Tradisional dengan kecil-kecilan dan keperluan sendiri. Komersial dengan perladangan, mesin, modal besar, tenaga buruh dan eksport.', 'Aku membandingkan dua jenis ekonomi. Ekonomi tradisional diusahakan kecil-kecilan untuk keperluan sendiri dan keluarga, manakala ekonomi komersial diusahakan secara perladangan dengan mesin dan jentera, modal besar dan tenaga buruh yang banyak untuk kegunaan tempatan dan eksport.', 'Betul! Pak Tani dan Petani Moden saling berpandangan dan tersenyum kerana perbezaan mereka dijelaskan.'),
(NULL, 'e8_n1_s3', 'hint', 'Lombong emas Sungai Lebir di Kelantan menggunakan kapal korek.', NULL, NULL),
(803, NULL, 'hint', 'Mendulang ialah kaedah tradisional. Kapal korek ialah jentera komersial.', 'Aku membezakan dua kaedah perlombongan. Kaedah tradisional ialah mendulang, manakala perlombongan komersial menggunakan jentera seperti kapal korek di lombong emas Sungai Lebir, Kelantan, dan ekonomi komersial menggalakkan pembukaan bandar di kawasan perlombongan.', 'Tepat! Penoreh Getah mengangguk kerana mendulang dan kapal korek tidak lagi tertukar.'),
(NULL, 'e8_n1_s4', 'hint', 'Getah dan kelapa sawit ialah sektor pertanian utama.', NULL, NULL),
(804, NULL, 'hint', 'Kedua-dua industri bermula sejak awal abad ke-20.', 'Penoreh Getah dan Petani Moden menceritakan sejarah ladang. Industri getah dan kelapa sawit bermula sejak awal abad ke-20 dan merupakan sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.', 'Betul! Penoreh Getah menepuk pokok getah tuanya sambil tersenyum bangga.'),
(NULL, 'e8_n1_s5', 'hint', 'Perabot daripada kayu getah ialah contoh industri hiliran.', NULL, NULL),
(805, NULL, 'hint', 'Lima manfaat. Pendapatan negara, pekerjaan, industri hiliran, industri asas tani dan biodiesel.', 'Aku menyusun lima manfaat getah dan sawit. Hasilnya dieksport untuk meningkatkan pendapatan negara, ladang menyediakan peluang pekerjaan, industri hiliran seperti perabot daripada kayu getah, industri asas tani memajukan makanan tempatan, dan sawit diproses menjadi biodiesel, minyak dan sabun.', 'Hebat! Kad-kad itu tersusun semula dan Penoreh Getah mengangkat ibu jarinya.'),
(NULL, 'e8_n1_s6', 'hint', 'Biodiesel ialah bahan api daripada bahan buangan organik.', NULL, NULL),
(806, NULL, 'hint', 'Hiliran berkembang daripada kegiatan ekonomi utama. Contohnya perabot daripada kayu getah.', 'Aku belajar dua istilah penting. Industri hiliran ialah kegiatan yang berkembang daripada kegiatan ekonomi utama, seperti perabot daripada kayu getah, manakala biodiesel ialah bahan buangan organik yang digunakan sebagai bahan api dan sawit turut menghasilkannya.', 'Betul! Pelawat ladang itu mencatat maksud industri hiliran dalam bukunya.'),
(NULL, 'e8_n1_s7', 'hint', 'Minyak mentah sawit ialah hasil sebelum diproses.', NULL, NULL),
(807, NULL, 'hint', 'Sarung tangan dan benang lateks daripada getah. Minyak mentah, minyak diproses dan sabun daripada sawit.', 'Aku mengasingkan hasil eksport. Sarung tangan dan benang lateks daripada getah, manakala minyak mentah sawit, minyak sawit yang diproses dan sabun daripada kelapa sawit.', 'Cekap! Label baharu ditampal di setiap kotak dan hasil eksport tidak lagi bercampur.'),
(NULL, 'e8_n1_s8', 'hint', 'Petroleum 1910, PETRONAS 1974, PROTON 1983.', NULL, NULL),
(808, NULL, 'hint', 'Mulakan dengan zaman awal pertanian dan perlombongan. Penutupnya PROTON pada 1983.', 'Kembara dari cangkul ke jentera berakhir dengan satu garis masa. Zaman awal dengan pertanian dan perlombongan tradisional, awal abad ke-20 dengan getah dan sawit secara perladangan, 1910 dengan petroleum di Miri, 1974 dengan PETRONAS dan 1983 dengan PROTON di Shah Alam.', 'Tahniah! Juruteknik menyerahkan sebilah sepana kecil kepadamu sebagai kenang-kenangan kembara.'),
(NULL, 'e8_n2_s1', 'hint', 'The Grand Old Lady, Miri ialah telaga minyak yang pertama.', NULL, NULL),
(809, NULL, 'hint', 'Petroleum bermula pada 1910 di Miri. PETRONAS ditubuhkan pada 1974.', 'Aku membetulkan borang pemeriksaan. Industri petroleum bermula pada 1910 di Miri, Sarawak, dengan telaga The Grand Old Lady, dan PETRONAS yang dimiliki sepenuhnya oleh kerajaan ditubuhkan pada 1974.', 'Tepat! Inspektor mencop borang itu LULUS dan Jurutera Pelantar Minyak tersenyum lega.'),
(NULL, 'e8_n2_s2', 'hint', 'Grand Prix Malaysia ialah sukan permotoran yang ditaja PETRONAS.', NULL, NULL),
(810, NULL, 'hint', 'Pelantar dan pusat pemprosesan untuk pekerjaan. Stesen minyak untuk usahawan. Universiti Teknologi PETRONAS untuk biasiswa.', 'Jurutera pelantar minyak menyenaraikan sumbangan industri petroleum. Ia membuka pekerjaan di pelantar dan pusat pemprosesan, melahirkan usahawan melalui stesen minyak, menaja Grand Prix Malaysia, memberi biasiswa ke Universiti Teknologi PETRONAS, dan memberi pulangan pendapatan tinggi kerana permintaan dunia.', 'Betul! Jurutera Pelantar Minyak mengangguk dan Inspektor mencatat nota baharu pada borangnya.'),
(NULL, 'e8_n2_s3', 'hint', 'Grand Prix Malaysia ialah contoh sukan permotoran.', NULL, NULL),
(811, NULL, 'hint', 'PETRONAS menaja sukan permotoran. Penganjuran sukan itu meningkatkan pendapatan negara.', 'Aku menjawab soalan wartawan tentang penajaan. PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia dan penganjuran sukan ini meningkatkan pendapatan negara.', 'Tepat! Wartawan itu menulis jawapan itu di bukunya sambil mengangguk.'),
(NULL, 'e8_n2_s4', 'hint', 'Proton Saga pada 1985. PERODUA pada 1993 dan Kancil pada 1994.', NULL, NULL),
(812, NULL, 'hint', 'Mulakan dengan PROTON pada 1983. Penutupnya usaha sama dengan Geely pada 2018.', 'Aku menyusun garis masa industri automotif. PROTON ditubuhkan pada 1983, Proton Saga dilancarkan pada Julai 1985, PERODUA ditubuhkan pada 1993, Kancil dikeluarkan pada 1994, kilang kedua PROTON dibina di Tanjung Malim pada 2005, dan PROTON bekerjasama dengan Geely pada 2018.', 'Hebat! Inspektor menampal garis masa itu di dinding kilang untuk dibaca para pekerja.'),
(NULL, 'e8_n2_s5', 'hint', 'Nippa ialah produk PERODUA yang dieksport ke United Kingdom.', NULL, NULL),
(813, NULL, 'hint', 'PROTON dengan Shah Alam, Saga dan Tanjung Malim. PERODUA dengan 1993, Kancil dan Nippa.', 'Aku memadankan butiran PROTON dan PERODUA. PROTON ditubuhkan di Shah Alam pada 1983, Proton Saga ialah model pertama negara pada Julai 1985 dan kilang kedua dibina di Tanjung Malim pada 2005, manakala PERODUA ditubuhkan pada 1993, Kancil dikeluarkan pada 1994 dan Nippa dieksport ke United Kingdom.', 'Betul! Pengunjung kilang itu mengangguk kerana akhirnya PROTON dan PERODUA mudah dibezakan.'),
(NULL, 'e8_n2_s6', 'hint', 'Tahun Melawat Malaysia dianjurkan sejak tahun 1990.', NULL, NULL),
(814, NULL, 'hint', 'Empat bukti. Air terjun hutan, jambatan gantung, gua batu kapur dan pantai.', 'Aku mencari empat bukti keindahan alam semula jadi. Air terjun hutan, pelancong di jambatan gantung, gua batu kapur dan pelancong bergambar di pantai. Kempen Tahun Melawat Malaysia telah dianjurkan sejak tahun 1990.', 'Cekap! Pemandu Pelancong tersenyum kerana keempat-empat tarikan alam itu dijumpai.'),
(NULL, 'e8_n2_s7', 'hint', 'Agropelancongan ialah inap desa bersama keluarga penduduk tempatan.', NULL, NULL),
(815, NULL, 'hint', 'Sejarah, alam, budaya, agropelancongan, dan sukan serta pameran antarabangsa.', 'Aku memadankan lima keistimewaan pelancongan. Tapak bersejarah seperti Kota A Famosa, alam seperti Gunung Kinabalu dan Gua Niah, keharmonian dan keunikan budaya, agropelancongan dengan inap desa, dan acara antarabangsa seperti Formula One dan LIMA.', 'Betul! Pemandu Pelancong menyusun lima keistimewaan itu di papan taklimat sambil tersenyum.'),
(NULL, 'e8_n2_s8', 'hint', 'Le Tour de Langkawi ialah perlumbaan basikal antarabangsa.', NULL, NULL),
(816, NULL, 'hint', 'Formula One di Sepang. Hutan Hujan di Sarawak. LIMA di Langkawi setiap dua tahun.', 'Aku memadankan acara antarabangsa. Formula One dianjurkan di Sepang, Le Tour de Langkawi ialah perlumbaan basikal antarabangsa, Festival Muzik Hutan Hujan Sedunia di Sarawak, dan LIMA ialah pameran maritim dan aeroangkasa di Pulau Langkawi setiap dua tahun.', 'Tepat! Pemandu Pelancong mengacukan jari ke peta dan semua acara berada di tempatnya.'),
(NULL, 'e8_n3_s1', 'hint', 'Kempen itu bernama Beli Barangan Buatan Malaysia.', NULL, NULL),
(817, NULL, 'hint', 'Poster itu menyebut tahun 1985. Contohnya perabot, elektrik dan elektronik, dan makanan.', 'Di kedai jenama Malaysia aku belajar tentang kempen Beli Barangan Buatan Malaysia yang dilancarkan pada tahun 1985. Contoh barangannya termasuk perabot, barangan elektrik dan elektronik serta produk makanan.', 'Betul! Pemilik kedai menepuk poster itu dan pelanggan lain turut mengangguk.'),
(NULL, 'e8_n3_s2', 'hint', 'Kereta dan motosikal ialah produk automotif.', NULL, NULL),
(818, NULL, 'hint', 'Sawit dengan minyak masak dan sabun. Buah dengan durian dan nanas. Petroleum dengan petrol, pelincir dan gas.', 'Aku menyusun rak kedai. Minyak masak dan sabun ialah produk pertanian daripada sawit, durian dan nanas ialah produk buah-buahan, minyak petrol, minyak pelincir dan gas memasak ialah produk petroleum, dan kereta serta motosikal ialah produk automotif.', 'Hebat! Rak kedai kini kemas, dan Peniaga E-Dagang tertawa kerana minyak pelincir sudah pergi ke rak yang betul.'),
(NULL, 'e8_n3_s3', 'hint', 'Tiga bidang. Pembangunan, perhubungan dan perdagangan.', NULL, NULL),
(819, NULL, 'hint', 'Empat bukti. Menara pencakar langit, jambatan dan jalan raya, gudang e-dagang, dan papan iklan carta menaik.', 'Aku mencari empat bukti pencapaian ekonomi pesat. Menara pencakar langit lambang pembangunan, jambatan, kereta api dan jalan raya lambang perhubungan moden yang terancang, gudang e-dagang dan papan iklan carta menaik menunjukkan perdagangan yang berkembang.', 'Cekap! Peniaga E-Dagang tersenyum kerana keempat-empat bukti itu dijumpai dengan cepat.'),
(NULL, 'e8_n3_s4', 'hint', 'E-dagang ialah urusan perniagaan melalui rangkaian Internet.', NULL, NULL),
(820, NULL, 'hint', 'Pembangunan dengan pencakar langit. Perhubungan dengan jaringan moden. Perdagangan dengan e-dagang melalui Internet.', 'Aku memadankan tiga pencapaian ekonomi. Pembangunan ialah bangunan pencakar langit sebagai lambang kemakmuran, perhubungan ialah jaringan moden yang terancang, perdagangan ialah e-dagang yang membuka peluang kepada rakyat, dan e-dagang bermaksud urusan perniagaan melalui rangkaian Internet.', 'Betul! Peniaga E-Dagang menyalin tiga pencapaian itu ke bukunya dengan teliti.'),
(NULL, 'e8_n3_s5', 'hint', 'Usahawan juga dibantu meningkatkan produktiviti.', NULL, NULL),
(821, NULL, 'hint', 'Kad itu menyebut sistem ekonomi, pasaran tempatan dan identiti negara.', 'Aku belajar mengapa kita bangga dengan barangan buatan Malaysia. Ia memajukan sistem ekonomi negara, memperluaskan pasaran produk tempatan, memperkenalkan identiti negara dan membantu usahawan meningkatkan produktiviti.', 'Tepat! Pelanggan di kedai itu mula memilih barangan tempatan di rak.'),
(NULL, 'e8_n3_s6', 'hint', 'Kad itu juga menyebut kestabilan sosial dan politik.', NULL, NULL),
(822, NULL, 'hint', 'Kemajuan ekonomi meningkatkan taraf hidup, infrastruktur dan daya saing negara.', 'Aku belajar kepentingan kemajuan ekonomi. Ia meningkatkan taraf hidup rakyat dengan lebih banyak peluang pekerjaan, membolehkan pelaburan dalam infrastruktur, menyumbang kepada kestabilan sosial dan politik serta meningkatkan daya saing negara.', 'Betul! Peniaga E-Dagang membuang soal selidik yang mengelirukan dan menggantikannya dengan kad ini.'),
(NULL, 'e8_n3_s7', 'hint', 'Tiga peringkat. Diri, masyarakat dan negara.', NULL, NULL),
(823, NULL, 'hint', 'Diri dengan setiap warganegara. Masyarakat dengan sokongan pembangunan. Negara dengan kemajuan yang dikongsi bersama.', 'Aku belajar tiga peringkat sokongan kepada ekonomi. Diri ialah setiap warganegara yang menyokong usaha meningkatkan ekonomi, masyarakat meningkatkan pendapatan negara melalui sokongan pembangunan, dan negara menikmati kemajuan ekonomi yang dikongsi bersama.', 'Tepat! Projek peniaga muda itu kini mempunyai tiga peringkat yang jelas.'),
(NULL, 'e8_n3_s8', 'hint', 'Tahun Melawat Malaysia dianjurkan sejak tahun 1990.', NULL, NULL),
(824, NULL, 'hint', 'Getah dan sawit sejak awal abad ke-20. Petroleum 1910 dan 1974. Automotif 1983 dan 1993. Pelancongan sejak 1990.', 'Kedai ditutup dengan rumusan empat industri. Getah dan kelapa sawit sejak awal abad ke-20, petroleum dan gas bermula 1910 di Miri dengan PETRONAS pada 1974, automotif dengan PROTON pada 1983 dan PERODUA pada 1993, dan pelancongan dengan Kempen Tahun Melawat Malaysia sejak 1990.', 'Tahniah! Pemilik kedai menyerahkan beg kertas berisi barangan buatan Malaysia kepadamu sebagai hadiah.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(141, 801, NULL, 'Tugasku menjaga mesin ladang supaya ekonomi berjalan. Jika aku keliru antara cara dahulu dan kini, kerja petani akan terganggu, {nama}.', 1),
(141, 801, NULL, 'Aku belajar bahawa setiap warganegara perlu menyokong usaha meningkatkan ekonomi negara supaya terus berkembang maju.', 2),
(141, 801, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, juruteknik yang menjaga jentera di ladang. Dengar keluhan petani dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(141, 801, 'e8_n1_s1', 'Selamat datang ke kembara aku, dari cangkul ke jentera. Di tepi petak sawah itu ada seorang petani tua yang masih tidak mahu menukar caranya.', 1),
(144, 801, 'e8_n1_s1', 'Aku masih dengan cangkul dan sabit. Tidak perlu mesin. Cangkul kedua di tepi pagar itu pun cukup, kerana modalnya kecil dan alatnya sederhana.', 2),
(144, 801, 'e8_n1_s1', 'Rumah kayu itu rumah petani seperti aku. Hasil sawah kami ambil untuk keperluan sendiri dan keluarga.', 3),
(141, 801, 'e8_n1_s1', 'Petak sawah kecil itu pula diusahakan secara kecil-kecilan, sebab itu cara ini dinamakan ekonomi tradisional.', 4),
(NULL, 801, 'e8_n1_s1', 'Aku akan cari empat buktinya dalam gambar. Cangkul di tepi petak, cangkul di tepi pagar, rumah kayu petani dan petak sawah kecil.', 5),
(144, 801, 'e8_n1_s1', 'Cari betul-betul, jangan menuduh. Jadi cara bertani aku ini sesuai untuk apa sebenarnya?', 6),
(145, 801, 'e8_n1_s2', 'Ladang kami diusahakan secara perladangan dengan mesin dan jentera. Kami memerlukan modal yang besar dan tenaga buruh yang banyak.', 1),
(144, 801, 'e8_n1_s2', 'Aku cuma ada cangkul. Apa bezanya cara kami, Juruteknik?', 2),
(141, 801, 'e8_n1_s2', 'Ekonomi tradisional diusahakan kecil-kecilan, dan tujuannya untuk keperluan sendiri dan keluarga.', 3),
(145, 801, 'e8_n1_s2', 'Ekonomi komersial pula diusahakan secara perladangan, dengan mesin dan jentera penuai. Hasilnya untuk kegunaan tempatan dan eksport.', 4),
(NULL, 801, 'e8_n1_s2', 'Aku akan padankan ciri setiap jenis ekonomi itu.', 5),
(145, 801, 'e8_n1_s2', 'Padankan dengan betul supaya pak tani faham. Dan walaupun cara kami berbeza, apakah yang sama antara kedua-duanya?', 6),
(NULL, 801, 'e8_n1_s3', 'Dua gambar ini tentang perlombongan. Yang mana tradisional, yang mana komersial?', 1),
(146, 801, 'e8_n1_s3', 'Kata datuk aku, dahulu orang mendulang untuk mencari bijih.', 2),
(141, 801, 'e8_n1_s3', 'Betul, mendulang ialah kaedah tradisional. Perlombongan komersial pula menggunakan jentera seperti kapal korek, contohnya di lombong emas Sungai Lebir, Kelantan.', 3),
(141, 801, 'e8_n1_s3', 'Apabila ekonomi komersial diperkenalkan, bandar-bandar mula dibuka di kawasan perlombongan.', 4),
(NULL, 801, 'e8_n1_s3', 'Nota di belakang gambar ini pun menyebutnya. Tradisional dengan mendulang, komersial dengan kapal korek.', 5),
(146, 801, 'e8_n1_s3', 'Jangan terbalik. Jadi apakah yang dibawa oleh ekonomi komersial kepada kawasan perlombongan itu?', 6),
(146, 801, 'e8_n1_s4', 'Pokok getah di sini sudah ditanam sejak lama. Datuk aku menoreh getah sejak zaman dahulu lagi.', 1),
(145, 801, 'e8_n1_s4', 'Kelapa sawit pun bermula dalam tempoh yang sama, malah ladang kami tumbuh bersamanya.', 2),
(141, 801, 'e8_n1_s4', 'Nota ini menyebut bahawa industri getah dan kelapa sawit bermula sejak awal abad ke-20. Ia sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.', 3),
(NULL, 801, 'e8_n1_s4', 'Aku akan semak nota dan tentukan bila kedua-dua industri bermula. Sejak awal abad ke-20.', 4),
(146, 801, 'e8_n1_s4', 'Jangan agak-agak, kerana tarikh mesti tepat. Jadi apakah yang dilakukan oleh industri lama ini kepada ekonomi negara?', 5),
(146, 801, 'e8_n1_s5', 'Kad-kad ini jatuh ke tanah. Siapa boleh susun semula manfaat getah dan sawit?', 1),
(146, 801, 'e8_n1_s5', 'Hasil getah dan sawit dieksport, seperti sarung tangan dan minyak. Itulah cara ia meningkatkan pendapatan negara.', 2),
(145, 801, 'e8_n1_s5', 'Perladangan memerlukan tenaga kerja yang banyak, jadi ia menyediakan peluang pekerjaan.', 3),
(141, 801, 'e8_n1_s5', 'Ia juga mewujudkan industri hiliran, contohnya pembuatan perabot daripada kayu getah. Ia memajukan industri asas tani dengan meningkatkan pengeluaran bahan makanan tempatan.', 4),
(145, 801, 'e8_n1_s5', 'Dan sawit diproses menjadi biodiesel, minyak dan sabun. Itulah cara ia membangunkan industri biodiesel.', 5),
(NULL, 801, 'e8_n1_s5', 'Aku akan padankan lima manfaat itu dengan penerangannya.', 6),
(146, 801, 'e8_n1_s5', 'Baik. Jadi apakah manfaat paling dekat dengan penduduk kampung kita?', 7),
(146, 801, 'e8_n1_s6', 'Industri hiliran dan biodiesel selalu dikelirukan. Aku hanya tahu menoreh getah.', 1),
(141, 801, 'e8_n1_s6', 'Nota ini menjelaskannya. Industri hiliran bermaksud kegiatan yang berkembang daripada kegiatan ekonomi utama, contohnya pembuatan perabot daripada kayu getah.', 2),
(141, 801, 'e8_n1_s6', 'Biodiesel pula bermaksud bahan buangan organik yang digunakan sebagai bahan api. Industri kelapa sawit turut menghasilkan biodiesel sawit.', 3),
(NULL, 801, 'e8_n1_s6', 'Aku akan baca nota dan pilih maksud yang betul. Industri hiliran ialah kegiatan yang berkembang daripada kegiatan ekonomi utama.', 4),
(146, 801, 'e8_n1_s6', 'Teliti, nanti pelawat salah faham. Jadi apakah yang ditambah oleh industri hiliran kepada negara?', 5),
(146, 801, 'e8_n1_s7', 'Label di kotak ini luntur. Apa yang dieksport daripada getah dan sawit?', 1),
(146, 801, 'e8_n1_s7', 'Aku tahu sarung tangan dibuat daripada getah. Benang lateks pun hasil getah yang dieksport untuk membuat barangan kenyal.', 2),
(145, 801, 'e8_n1_s7', 'Kelapa sawit pula ada pelbagai bentuk. Minyak mentah sawit ialah hasil sebelum diproses, dan minyak sawit diproses ialah hasil selepas diproses untuk dieksport.', 3),
(141, 801, 'e8_n1_s7', 'Sabun pula produk yang diproses daripada kelapa sawit.', 4),
(NULL, 801, 'e8_n1_s7', 'Aku akan padankan hasil dengan sumbernya.', 5),
(146, 801, 'e8_n1_s7', 'Baik. Tetapi apakah kesan hasil eksport ini kepada negara kita?', 6),
(144, 801, 'e8_n1_s8', 'Juruteknik, ringkaskan perubahan dari dahulu hingga kini. Apa yang hilang, apa yang kekal?', 1),
(141, 801, 'e8_n1_s8', 'Pada zaman awal, pertanian dan perlombongan tradisional diusahakan kecil-kecilan. Pada awal abad ke-20, industri getah dan kelapa sawit berkembang secara perladangan.', 2),
(141, 801, 'e8_n1_s8', 'Industri petroleum bermula pada 1910 di Miri, Sarawak. PETRONAS ditubuhkan pada 1974 dan dimiliki sepenuhnya oleh kerajaan.', 3),
(141, 801, 'e8_n1_s8', 'PROTON pula ditubuhkan pada 1983 di Shah Alam, Selangor.', 4),
(NULL, 801, 'e8_n1_s8', 'Aku akan susun peristiwa mengikut peringkat perkembangan ekonomi itu.', 5),
(144, 801, 'e8_n1_s8', 'Ingat, kemajuan datang secara berperingkat. Jadi dari mana bermulanya kemajuan ekonomi kita?', 6),
(142, 802, NULL, 'Tugasku memeriksa mutu dan fakta. Jika satu cop salah, seluruh laporan ekonomi menjadi cacat, {nama}.', 1),
(142, 802, NULL, 'Aku belajar bahawa pelbagai kegiatan ekonomi menjana pendapatan dan memajukan negara.', 2),
(142, 802, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, inspektor yang memeriksa kilang dan industri. Semak setiap borang dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(147, 802, 'e8_n2_s1', 'Inspektor, borang ini menulis industri petroleum bermula pada 1974. Betulkah begitu?', 1),
(NULL, 802, 'e8_n2_s1', 'Aku ragu. Mari semak nota dahulu.', 2),
(142, 802, 'e8_n2_s1', 'Nota menyebut industri petroleum di negara kita bermula pada tahun 1910 di Miri, Sarawak. The Grand Old Lady, Miri ialah telaga minyak yang pertama di negara kita.', 3),
(147, 802, 'e8_n2_s1', 'Tahun 1974 itu ialah penubuhan PETRONAS, iaitu Petroliam Nasional Berhad. Ia dimiliki sepenuhnya oleh kerajaan Malaysia.', 4),
(NULL, 802, 'e8_n2_s1', 'Aku akan baca nota sebelum mencop. Bermula 1910 di Miri, dan PETRONAS ditubuhkan pada 1974.', 5),
(142, 802, 'e8_n2_s1', 'Jika cop LULUS salah, kita semua malu. Jadi apakah kejayaan penubuhan PETRONAS itu?', 6),
(147, 802, 'e8_n2_s2', 'Industri ini membuka kerja kepada ramai orang, iaitu pekerja di pelantar minyak dan pusat pemprosesan.', 1),
(NULL, 802, 'e8_n2_s2', 'Dan ia juga melahirkan usahawan, seperti mereka yang membuka stesen minyak.', 2),
(147, 802, 'e8_n2_s2', 'Betul. PETRONAS pula penaja utama sukan permotoran, iaitu Grand Prix Malaysia, dan itu meningkatkan pendapatan negara.', 3),
(142, 802, 'e8_n2_s2', 'Ada juga biasiswa untuk melanjutkan pelajaran ke Universiti Teknologi PETRONAS. Dan permintaan tinggi dunia terhadap petroleum memberi pulangan pendapatan yang tinggi.', 4),
(NULL, 802, 'e8_n2_s2', 'Aku akan padankan sumbangan itu dengan penerangannya.', 5),
(142, 802, 'e8_n2_s2', 'Jangan cop dahulu sebelum semak. Jadi apakah pendapat kau tentang industri petroleum ini?', 6),
(147, 802, 'e8_n2_s3', 'Seorang wartawan bertanya, buat apa PETRONAS menaja perlumbaan?', 1),
(NULL, 802, 'e8_n2_s3', 'Fikir tentang pendapatan negara.', 2),
(142, 802, 'e8_n2_s3', 'Nota ini menyebut bahawa PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia.', 3),
(142, 802, 'e8_n2_s3', 'Penganjuran sukan ini meningkatkan pendapatan negara.', 4),
(NULL, 802, 'e8_n2_s3', 'Aku akan baca nota penajaan itu dan jawab. Penganjuran sukan permotoran meningkatkan pendapatan negara.', 5),
(142, 802, 'e8_n2_s3', 'Jawapan pendek dan tepat. Jadi mengapakah penajaan sukan itu berbaloi kepada negara dan rakyat?', 6),
(142, 802, 'e8_n2_s4', 'Aku Inspektor Kilang Automotif. Tarikh-tarikh dalam fail kilang ini bercampur-campur.', 1),
(147, 802, 'e8_n2_s4', 'PROTON ditubuhkan pada 1983 di Shah Alam, Selangor. Pada Julai 1985, Proton Saga dilancarkan sebagai model kereta pertama negara.', 2),
(142, 802, 'e8_n2_s4', 'PERODUA ditubuhkan pada 1993, dan model pertama PERODUA, Kancil, dikeluarkan pada 1994.', 3),
(142, 802, 'e8_n2_s4', 'Pada 2005, kilang kedua PROTON dibina di Tanjung Malim, Perak. Pada 2018, PROTON menjalin usaha sama dengan Geely Holding Group.', 4),
(NULL, 802, 'e8_n2_s4', 'Aku akan susun peristiwa itu mengikut tahun.', 5),
(142, 802, 'e8_n2_s4', 'Laporan perlu dihantar sebelum waktu pejabat tamat. Dan apakah perasaan kita terhadap pencapaian automotif negara ini?', 6),
(147, 802, 'e8_n2_s5', 'Pengunjung kilang tidak tahu beza PROTON dan PERODUA. Tolong padankan butiran dengan betul.', 1),
(142, 802, 'e8_n2_s5', 'PROTON ditubuhkan dengan kilang pertama di Shah Alam pada tahun 1983. Proton Saga ialah model kereta pertama negara pada Julai 1985.', 2),
(142, 802, 'e8_n2_s5', 'Kilang kedua PROTON dibina di Tanjung Malim, Perak pada tahun 2005.', 3),
(142, 802, 'e8_n2_s5', 'PERODUA ditubuhkan pada tahun 1993. Kancil ialah model pertama PERODUA pada tahun 1994, dan produk PERODUA bernama Nippa dieksport ke United Kingdom.', 4),
(NULL, 802, 'e8_n2_s5', 'Aku akan padankan syarikat dengan butirannya.', 5),
(147, 802, 'e8_n2_s5', 'Jangan rosakkan reputasi kilang. Dan apakah yang didorong oleh industri automotif ini?', 6),
(148, 802, 'e8_n2_s6', 'Pelancong datang ke Malaysia kerana keindahan alam. Cari buktinya dalam gambar, Inspektor.', 1),
(NULL, 802, 'e8_n2_s6', 'Jangan lupa Tahun Melawat Malaysia.', 2),
(148, 802, 'e8_n2_s6', 'Betul. Kempen Tahun Melawat Malaysia dianjurkan sejak tahun 1990 untuk menarik pelancong. Lihat air terjun hutan itu, dan pelancong di jambatan gantung.', 3),
(148, 802, 'e8_n2_s6', 'Lihat juga gua batu kapur itu, dan pelancong yang bergambar di pantai.', 4),
(NULL, 802, 'e8_n2_s6', 'Air terjun hutan, jambatan gantung, gua batu kapur dan pantai. Aku akan cari keempat-empatnya.', 5),
(148, 802, 'e8_n2_s6', 'Teliti, pelancong itu cerewet. Jadi apakah yang perlu kita lakukan terhadap alam semula jadi ini?', 6),
(148, 802, 'e8_n2_s7', 'Pelancong suka sejarah, alam dan budaya. Padankan dengan betul, Inspektor.', 1),
(NULL, 802, 'e8_n2_s7', 'Dan makanan serta inap desa juga.', 2),
(148, 802, 'e8_n2_s7', 'Tapak dan bangunan bersejarah ialah Kota A Famosa, Candi Bukit Batu Pahat dan Istana Kenangan. Keindahan alam semula jadi pula Gunung Kinabalu, Pulau Langkawi dan Gua Niah.', 3),
(148, 802, 'e8_n2_s7', 'Keharmonian dan keunikan budaya bermaksud hidup pelbagai kaum menjamin keselamatan dan menarik pelancong. Agropelancongan ialah konsep inap desa bersama keluarga penduduk tempatan.', 4),
(148, 802, 'e8_n2_s7', 'Sukan, muzik dan pameran antarabangsa ialah Formula One, Le Tour de Langkawi, Festival Muzik Hutan Hujan dan LIMA.', 5),
(NULL, 802, 'e8_n2_s7', 'Aku akan padankan keistimewaan itu dengan penerangannya.', 6),
(148, 802, 'e8_n2_s7', 'Mesyuarat bermula sebentar lagi. Jadi apakah yang turut menjadi tarikan pelancong, selain sejarah dan alam?', 7),
(148, 802, 'e8_n2_s8', 'Formula One di mana? LIMA di mana? Senarai ini kusut.', 1),
(142, 802, 'e8_n2_s8', 'Perlumbaan Formula One dianjurkan di Sepang. Le Tour de Langkawi ialah perlumbaan basikal antarabangsa.', 2),
(148, 802, 'e8_n2_s8', 'Festival Muzik Hutan Hujan Sedunia dianjurkan di Sarawak. LIMA pula pameran maritim dan aeroangkasa yang dianjurkan di Pulau Langkawi setiap dua tahun.', 3),
(NULL, 802, 'e8_n2_s8', 'Aku akan padankan acara itu dengan tempat atau cirinya.', 4),
(148, 802, 'e8_n2_s8', 'Padankan dengan betul, kerana pelancong menunggu. Jadi apakah yang dibawa oleh acara antarabangsa ini?', 5),
(143, 803, NULL, 'Tugasku menyusun rak dengan barangan buatan Malaysia dan menceritakan kisahnya. Jika aku tersilap, pelanggan akan hilang kepercayaan, {nama}.', 1),
(143, 803, NULL, 'Aku belajar bahawa membeli barangan buatan Malaysia memajukan ekonomi dan menimbulkan rasa bangga terhadap negara.', 2),
(143, 803, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemilik kedai jenama Malaysia. Layan pelanggan dengan jujur. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(149, 803, 'e8_n3_s1', 'Poster kempen di dinding kedai ini dilancarkan bila, Pakcik?', 1),
(NULL, 803, 'e8_n3_s1', 'Aku tahu, tetapi aku mahu pelanggan menjawab sendiri.', 2),
(143, 803, 'e8_n3_s1', 'Nota di bawah poster ini menyebut kempen ''Beli Barangan Buatan Malaysia'' dilancarkan pada tahun 1985.', 3),
(143, 803, 'e8_n3_s1', 'Antara barangan buatan Malaysia termasuklah perabot, barangan elektrik dan elektronik serta produk makanan.', 4),
(NULL, 803, 'e8_n3_s1', 'Aku akan baca nota di bawah poster itu. Tahun 1985, dengan perabot, elektrik dan elektronik, serta makanan.', 5),
(149, 803, 'e8_n3_s1', 'Jawab betul, nanti aku marah. Jadi apakah faedah membeli barangan tempatan kepada ekonomi negara?', 6),
(149, 803, 'e8_n3_s2', 'Aku letak minyak pelincir di rak buah-buahan tadi. Salahkah?', 1),
(NULL, 803, 'e8_n3_s2', 'Itu salah. Mari kita susun semula.', 2),
(143, 803, 'e8_n3_s2', 'Minyak masak dan sabun ialah produk pertanian daripada sawit. Buah durian dan buah nanas pula produk pertanian berupa buah-buahan.', 3),
(143, 803, 'e8_n3_s2', 'Minyak petrol ialah bahan api kenderaan daripada petroleum. Minyak pelincir kenderaan melincirkan enjin, dan gas untuk memasak digunakan di dapur.', 4),
(143, 803, 'e8_n3_s2', 'Kereta dan motosikal pula produk automotif keluaran negara.', 5),
(NULL, 803, 'e8_n3_s2', 'Aku akan padankan produk dengan kategorinya.', 6),
(149, 803, 'e8_n3_s2', 'Cepat, aku mahu keluar. Jadi mengapa kita patut berbangga dengan produk ini?', 7),
(149, 803, 'e8_n3_s3', 'Apa bukti pencapaian ekonomi pesat negara, Pakcik?', 1),
(143, 803, 'e8_n3_s3', 'Lihat sekeliling, ada tiga bidang. Pembangunan, perhubungan dan perdagangan.', 2),
(149, 803, 'e8_n3_s3', 'Menara pencakar langit itu pembangunan. Jambatan, kereta api dan jalan raya itu perhubungan moden yang terancang.', 3),
(149, 803, 'e8_n3_s3', 'Gudang e-dagang itu perdagangan yang semakin berkembang, dan papan iklan carta menaik itu pun menunjukkan e-dagang semakin berkembang.', 4),
(NULL, 803, 'e8_n3_s3', 'Menara pencakar langit, jambatan dan jalan raya, gudang e-dagang, dan papan iklan carta menaik. Aku akan cari keempat-empatnya.', 5),
(149, 803, 'e8_n3_s3', 'Fikir pembangunan, perhubungan dan perdagangan. Jadi bagaimana perasaan kau melihat semua pencapaian ini?', 6),
(149, 803, 'e8_n3_s4', 'Pembangunan, perhubungan dan perdagangan, apa maksud setiap satu, Pakcik?', 1),
(143, 803, 'e8_n3_s4', 'Pembangunan ialah bangunan pencakar langit sebagai lambang kemakmuran negara. Perhubungan pula jaringan moden terancang yang mendorong kesinambungan pembangunan.', 2),
(143, 803, 'e8_n3_s4', 'Perdagangan ialah kegiatan e-dagang yang membuka peluang kepada rakyat. E-dagang bermaksud proses menjalankan urusan perniagaan melalui rangkaian Internet.', 3),
(NULL, 803, 'e8_n3_s4', 'Aku akan padankan pencapaian itu dengan penerangannya.', 4),
(149, 803, 'e8_n3_s4', 'Jangan campur, kerana aku akan menyalin ke buku. Jadi apa yang e-dagang berikan kepada rakyat?', 5),
(149, 803, 'e8_n3_s5', 'Mengapa perlu bangga dengan barangan buatan Malaysia, Pakcik?', 1),
(143, 803, 'e8_n3_s5', 'Ada sebab ekonomi dan sebab identiti. Kad ini menyebut rasa bangga memajukan sistem ekonomi negara dan memperluaskan pasaran produk tempatan.', 2),
(143, 803, 'e8_n3_s5', 'Ia juga memperkenalkan identiti negara dan membantu usahawan meningkatkan produktiviti.', 3),
(NULL, 803, 'e8_n3_s5', 'Aku akan baca kad dan memilih jawapan yang betul. Memajukan ekonomi, memperluaskan pasaran tempatan dan memperkenalkan identiti negara.', 4),
(149, 803, 'e8_n3_s5', 'Pilih betul-betul, nanti aku beli barang luar. Jadi apakah pilihan kau semasa membeli-belah nanti?', 5),
(149, 803, 'e8_n3_s6', 'Soal selidik ini mengelirukan. Pernyataan mana yang benar?', 1),
(149, 803, 'e8_n3_s6', 'Kemajuan ekonomi bukankah menambah kemiskinan?', 2),
(143, 803, 'e8_n3_s6', 'Tidak. Kad ini menyebut kemajuan ekonomi meningkatkan taraf hidup rakyat dengan menyediakan lebih banyak peluang pekerjaan.', 3),
(143, 803, 'e8_n3_s6', 'Ia juga membolehkan pelaburan dalam infrastruktur seperti jalan raya dan jambatan, menyumbang kepada kestabilan sosial dan politik, serta meningkatkan daya saing negara.', 4),
(NULL, 803, 'e8_n3_s6', 'Aku akan baca kad dan tentukan pernyataan yang betul. Meningkatkan taraf hidup, infrastruktur dan daya saing negara.', 5),
(149, 803, 'e8_n3_s6', 'Jangan terpengaruh dengan pernyataan pelik. Jadi apakah kesimpulan kau tentang kemajuan ekonomi?', 6),
(149, 803, 'e8_n3_s7', 'Sebagai warganegara, apa peranan setiap peringkat dalam menyokong ekonomi?', 1),
(143, 803, 'e8_n3_s7', 'Fikir tiga peringkat. Diri ialah setiap warganegara yang menyokong usaha meningkatkan ekonomi negara.', 2),
(143, 803, 'e8_n3_s7', 'Masyarakat pula, sokongan dalam pembangunan ekonomi meningkatkan pendapatan negara.', 3),
(143, 803, 'e8_n3_s7', 'Dan negara, peningkatan pendapatan dan kemajuan ekonomi dikongsi bersama.', 4),
(149, 803, 'e8_n3_s7', 'Aku keliru antara diri, masyarakat dan negara.', 5),
(NULL, 803, 'e8_n3_s7', 'Aku akan padankan setiap peringkat dengan peranannya.', 6),
(149, 803, 'e8_n3_s7', 'Jawab untuk projek ini. Jadi mengapa kita perlu menyokong ekonomi negara bersama-sama?', 7),
(149, 803, 'e8_n3_s8', 'Pakcik, boleh rumuskan Unit 8 sebelum kedai ditutup?', 1),
(143, 803, 'e8_n3_s8', 'Ada empat industri utama dan dua jenis ekonomi. Getah dan kelapa sawit ialah sektor pertanian utama sejak awal abad ke-20.', 2),
(143, 803, 'e8_n3_s8', 'Petroleum dan gas bermula pada 1910 di Miri, dan PETRONAS ditubuhkan pada 1974. Automotif bermula apabila PROTON ditubuhkan pada 1983 dan PERODUA pada 1993.', 3),
(143, 803, 'e8_n3_s8', 'Pelancongan pula dimajukan melalui Kempen Tahun Melawat Malaysia sejak tahun 1990.', 4),
(NULL, 803, 'e8_n3_s8', 'Aku akan padankan industri itu dengan cirinya.', 5),
(149, 803, 'e8_n3_s8', 'Teliti, kerana ini peperiksaan kecil. Jadi mengapa kegiatan ekonomi yang pelbagai penting kepada negara?', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (8, 8)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(801, 8, 'Perkembangan awal ekonomi negara melibatkan sektor...', 'pelancongan dan automotif', 'petroleum dan e-dagang', 'perkhidmatan dan sukan', 'pertanian dan perlombongan', 'D', 'Sebelum industri moden.', 'Perkembangan awal ekonomi negara melibatkan sektor pertanian dan perlombongan.'),
(802, 8, 'Manakah ciri ekonomi tradisional?', 'Diusahakan secara perladangan untuk eksport', 'Menggunakan mesin dan jentera penuai', 'Diusahakan secara kecil-kecilan untuk keperluan sendiri dan keluarga', 'Memerlukan modal besar dan tenaga buruh banyak', 'C', 'Cangkul dan sabit.', 'Ekonomi tradisional diusahakan kecil-kecilan dan bertujuan untuk keperluan sendiri dan keluarga.'),
(803, 8, 'Peralatan yang digunakan dalam ekonomi tradisional ialah...', 'jentera penuai', 'cangkul dan sabit', 'kapal korek', 'mesin moden', 'B', 'Peralatan mudah.', 'Ekonomi tradisional menggunakan peralatan mudah seperti cangkul dan sabit.'),
(804, 8, 'Ekonomi komersial dalam sektor pertanian diusahakan secara...', 'perladangan', 'kecil-kecilan', 'mendulang', 'berkelompok sahaja', 'A', 'Menggunakan mesin dan jentera.', 'Ekonomi komersial diusahakan secara perladangan.'),
(805, 8, 'Ekonomi komersial bertujuan untuk...', 'keperluan sendiri dan keluarga sahaja', 'bersara awal', 'menggantikan pertanian', 'kegunaan tempatan dan eksport', 'D', 'Modal besar.', 'Ekonomi komersial bertujuan untuk kegunaan tempatan dan eksport.'),
(806, 8, 'Kaedah tradisional aktiviti perlombongan ialah...', 'kapal korek', 'pelantar minyak', 'mendulang', 'jentera penuai', 'C', 'Di sungai.', 'Kaedah tradisional perlombongan ialah mendulang.'),
(807, 8, 'Jentera yang digunakan dalam perlombongan komersial ialah...', 'cangkul', 'kapal korek', 'sabit', 'dulang', 'B', 'Contoh di Sungai Lebir, Kelantan.', 'Kapal korek digunakan dalam perlombongan komersial.'),
(808, 8, 'Pengenalan ekonomi komersial menggalakkan...', 'pembukaan bandar-bandar di kawasan perlombongan', 'pembubaran semua ladang', 'penghentian eksport', 'pengurangan peluang pekerjaan', 'A', 'Perubahan membawa kemajuan.', 'Ekonomi komersial menggalakkan pembukaan bandar di kawasan perlombongan.'),
(809, 8, 'Industri getah dan kelapa sawit bermula sejak...', 'tahun 1957', 'tahun 1983', 'tahun 1990', 'awal abad ke-20', 'D', 'Sektor pertanian utama.', 'Industri getah dan kelapa sawit bermula sejak awal abad ke-20.'),
(810, 8, 'Contoh hasil getah yang dieksport ialah...', 'minyak mentah dan sabun', 'kereta dan motosikal', 'sarung tangan dan benang lateks', 'minyak pelincir dan gas', 'C', 'Pasaran antarabangsa.', 'Hasil getah yang dieksport termasuk sarung tangan dan benang lateks.'),
(811, 8, 'Contoh hasil kelapa sawit yang dieksport ialah...', 'sarung tangan', 'minyak mentah dan minyak yang telah diproses', 'benang lateks', 'perabot kayu getah', 'B', 'Juga dijadikan sabun.', 'Hasil kelapa sawit yang dieksport ialah minyak mentah dan minyak yang telah diproses.'),
(812, 8, 'Industri hiliran bermaksud...', 'kegiatan yang berkembang daripada kegiatan ekonomi utama', 'kegiatan menanam padi secara kecil-kecilan', 'kegiatan menyewa tanah', 'kegiatan menjual barangan di pasar', 'A', 'Contoh: perabot kayu getah.', 'Industri hiliran berkembang daripada kegiatan ekonomi utama, contohnya pembuatan perabot daripada kayu getah.'),
(813, 8, 'Biodiesel bermaksud...', 'minyak masak daripada sawit', 'gas memasak', 'minyak petrol', 'bahan buangan organik yang digunakan sebagai bahan api', 'D', 'Dihasilkan oleh industri sawit.', 'Biodiesel ialah bahan buangan organik yang digunakan sebagai bahan api.'),
(814, 8, 'Industri petroleum di negara kita bermula pada tahun...', '1974 di Kuala Lumpur', '1983 di Shah Alam', '1910 di Miri, Sarawak', '1990 di Langkawi', 'C', 'Telaga pertama di Miri.', 'Industri petroleum bermula pada tahun 1910 di Miri, Sarawak.'),
(815, 8, 'PETRONAS ditubuhkan pada tahun...', '1910', '1974', '1983', '1993', 'B', 'Dimiliki sepenuhnya oleh kerajaan.', 'PETRONAS ditubuhkan pada tahun 1974 dan dimiliki sepenuhnya oleh kerajaan Malaysia.'),
(816, 8, 'Telaga minyak yang pertama di negara kita ialah...', 'The Grand Old Lady, Miri', 'Menara Berkembar Petronas', 'Pusat Pemprosesan Kerteh', 'Pelantar Kinabalu', 'A', 'Terletak di Sarawak.', 'The Grand Old Lady, Miri ialah telaga minyak pertama di negara kita.'),
(817, 8, 'Industri petroleum melahirkan usahawan menerusi...', 'penanaman padi', 'perlombongan bijih timah', 'penerbitan buku', 'pembukaan stesen minyak', 'D', 'Contoh perniagaan kecil.', 'Industri petroleum melahirkan usahawan melalui pembukaan stesen minyak.'),
(818, 8, 'Universiti yang menerima biasiswa daripada industri petroleum ialah...', 'Universiti Malaya', 'Universiti Putra Malaysia', 'Universiti Teknologi PETRONAS', 'Universiti Sains Malaysia', 'C', 'Biasiswa pelajaran.', 'Industri petroleum menyediakan biasiswa untuk melanjutkan pelajaran ke Universiti Teknologi PETRONAS.'),
(819, 8, 'PETRONAS ialah penaja utama sukan...', 'badminton sahaja', 'permotoran seperti Grand Prix Malaysia', 'renang sahaja', 'gimnastik sahaja', 'B', 'Meningkatkan pendapatan negara.', 'PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia.'),
(820, 8, 'Industri automotif di negara kita mula diperkenalkan pada tahun...', '1983', '1974', '1990', '2005', 'A', 'Kilang pertama di Shah Alam.', 'Industri automotif mula diperkenalkan pada tahun 1983.'),
(821, 8, 'PROTON ialah singkatan bagi...', 'Perusahaan Otomobil Kedua Sdn. Bhd.', 'Petroliam Nasional Berhad', 'Persatuan Otomobil Negara', 'Perusahaan Otomobil Nasional Sdn. Bhd.', 'D', 'Kilang kereta nasional yang pertama.', 'PROTON ialah Perusahaan Otomobil Nasional Sdn. Bhd.'),
(822, 8, 'Model kereta pertama negara yang dikeluarkan pada Julai 1985 ialah...', 'Kancil', 'Nippa', 'Proton Saga', 'Iswara Aeroback', 'C', 'Pemenang pertandingan nama ialah Encik Ismail bin Jaafar.', 'Proton Saga ialah model kereta pertama negara pada Julai 1985.'),
(823, 8, 'Kilang kedua PROTON dibina di...', 'Shah Alam, Selangor pada tahun 1983', 'Tanjung Malim, Perak pada tahun 2005', 'Miri, Sarawak pada tahun 1910', 'Sepang, Selangor pada tahun 1999', 'B', 'Selepas kilang di Shah Alam.', 'Kilang kedua PROTON dibina di Tanjung Malim, Perak pada tahun 2005.'),
(824, 8, 'PERODUA ditubuhkan pada tahun...', '1993', '1983', '1974', '2005', 'A', 'Model pertamanya Kancil.', 'PERODUA ditubuhkan pada tahun 1993.'),
(825, 8, 'Model pertama PERODUA ialah...', 'Saga', 'Nippa', 'Proton Persona', 'Kancil', 'D', 'Dikeluarkan pada tahun 1994.', 'Model pertama PERODUA, Kancil, dikeluarkan pada tahun 1994.'),
(826, 8, 'Pada tahun 2018, PROTON menjalin usaha sama dengan...', 'Perusahaan Otomobil Kedua', 'Kementerian Pelancongan', 'Geely Holding Group', 'Universiti Teknologi PETRONAS', 'C', 'Untuk mengeluarkan model baharu.', 'Pada tahun 2018, PROTON menjalin usaha sama dengan Geely Holding Group.'),
(827, 8, 'Kempen Tahun Melawat Malaysia dianjurkan sejak tahun...', '1985', '1990', '1974', '1983', 'B', 'Untuk menarik kedatangan pelancong.', 'Kempen Tahun Melawat Malaysia dianjurkan sejak tahun 1990.'),
(828, 8, 'Manakah keistimewaan Malaysia yang menjadi tarikan pelancong?', 'Keharmonian masyarakat dan keunikan budaya', 'Kekurangan flora dan fauna', 'Tapak bersejarah yang dirobohkan', 'Peperangan antara kaum', 'A', 'Keselamatan pelancong terjamin.', 'Keharmonian hidup pelbagai kaum menjamin keselamatan pelancong dan keunikan budaya menarik mereka.'),
(829, 8, 'Agropelancongan ialah pelancongan yang berasaskan...', 'bangunan pencakar langit', 'sukan permotoran sahaja', 'perlombongan bijih timah sahaja', 'pertanian, perikanan, penternakan dan industri asas tani', 'D', 'Konsep inap desa.', 'Agropelancongan berasaskan pertanian, perikanan, penternakan dan industri asas tani.'),
(830, 8, 'LIMA ialah pameran antarabangsa yang dianjurkan setiap...', 'tahun di Sepang, Selangor', 'lima tahun di Kuching, Sarawak', 'dua tahun di Pulau Langkawi, Kedah', 'dua tahun di Miri, Sarawak', 'C', 'Pameran maritim dan aeroangkasa.', 'LIMA ialah pameran maritim dan aeroangkasa antarabangsa yang dianjurkan setiap dua tahun di Pulau Langkawi.'),
(831, 8, 'Kempen ''Beli Barangan Buatan Malaysia'' dilancarkan pada tahun...', '1990', '1985', '1974', '1993', 'B', 'Menyokong produk tempatan.', 'Kempen ''Beli Barangan Buatan Malaysia'' dilancarkan pada tahun 1985.'),
(832, 8, 'E-dagang bermaksud...', 'proses menjalankan urusan perniagaan melalui rangkaian Internet', 'proses menanam padi secara kecil-kecilan', 'proses mendulang bijih timah', 'proses mengeluarkan kereta di kilang', 'A', 'Perdagangan dalam talian.', 'E-dagang bermaksud proses menjalankan urusan perniagaan melalui rangkaian Internet.'),
(833, 8, 'Pencapaian pesat ekonomi negara dapat dilihat menerusi...', 'pertanian tradisional sahaja', 'penutupan kilang', 'pengurangan jalan raya', 'pembangunan, perhubungan dan perdagangan', 'D', 'Infrastruktur dan e-dagang.', 'Pencapaian pesat ekonomi dilihat menerusi pembangunan infrastruktur, perhubungan moden dan e-dagang.'),
(834, 8, 'Apakah kepentingan rasa bangga terhadap barangan buatan Malaysia?', 'Menjatuhkan produk tempatan', 'Menyembunyikan identiti negara', 'Memperkenalkan identiti negara dan memperluaskan pasaran tempatan', 'Mengurangkan produktiviti usahawan', 'C', 'Fikirkan usahawan tempatan.', 'Rasa bangga memajukan ekonomi, memperluaskan pasaran tempatan dan memperkenalkan identiti negara.'),
(835, 8, 'Apakah kepentingan menyokong usaha meningkatkan ekonomi negara?', 'Meningkatkan kemiskinan', 'Menyediakan peluang pekerjaan dan meningkatkan pendapatan negara', 'Menjejaskan kemakmuran negara', 'Menutup industri tempatan', 'B', 'Pendapatan dikongsi bersama.', 'Sokongan membawa peluang pekerjaan, pendapatan negara dan kemajuan yang dikongsi bersama.'),
(836, 8, 'Seorang petani menanam padi di petak kecil dengan cangkul hanya untuk makan sekeluarga. Seorang lagi mengusahakan ladang luas dengan jentera untuk dieksport. Apakah kesimpulan yang paling tepat?', 'Yang pertama ekonomi tradisional dan yang kedua ekonomi komersial', 'Kedua-duanya ekonomi komersial kerana sama-sama menanam tanaman', 'Yang pertama ekonomi komersial dan yang kedua ekonomi tradisional', 'Kedua-duanya ekonomi tradisional kerana sama-sama bekerja di sawah', 'A', 'Lihat skala, alat dan tujuan.', 'Kecil-kecilan, alat mudah dan untuk keluarga ialah ekonomi tradisional, manakala perladangan, jentera dan eksport ialah ekonomi komersial.'),
(837, 8, 'Kilang membuat perabot daripada kayu pokok getah yang sudah tidak menghasilkan susu. Apakah jenis industri ini?', 'Industri biodiesel yang menggunakan bahan buangan organik', 'Ekonomi tradisional yang diusahakan untuk keperluan sendiri', 'Kegiatan perlombongan menggunakan kapal korek', 'Industri hiliran yang berkembang daripada kegiatan ekonomi utama', 'D', 'Ingat contoh hiliran dalam kisah ladang.', 'Perabot daripada kayu getah berkembang daripada kegiatan utama menanam getah, maka ia industri hiliran.'),
(838, 8, 'Mengapakah ladang kelapa sawit membantu mengurangkan pengangguran penduduk sekitar?', 'Ladang sawit tidak memerlukan sebarang pekerja', 'Semua hasil sawit hanya digunakan oleh pemilik ladang', 'Perladangan memerlukan tenaga kerja yang banyak', 'Sawit hanya ditanam untuk keperluan sendiri dan keluarga', 'C', 'Fikirkan skala perladangan.', 'Perladangan memerlukan buruh yang banyak, jadi ia menyediakan peluang pekerjaan kepada penduduk.'),
(839, 8, 'Penganjuran Grand Prix Malaysia ditaja oleh PETRONAS. Manakah kesan yang paling dekat dengan penajaan itu?', 'Industri petroleum dihentikan di Miri', 'Pendapatan negara meningkat melalui penganjuran sukan permotoran', 'Semua kilang kereta ditutup', 'Pelancong dilarang memasuki negara', 'B', 'Hubungkan penaja dengan pendapatan.', 'PETRONAS ialah penaja utama sukan permotoran dan penganjuran sukan itu meningkatkan pendapatan negara.'),
(840, 8, 'Proton Saga dilancarkan pada Julai 1985, manakala PERODUA ditubuhkan pada 1993. Apakah kesimpulan tentang industri automotif negara?', 'Negara mempunyai lebih daripada satu pengeluar kereta sendiri', 'Negara tidak pernah mengeluarkan kereta sendiri', 'PERODUA ditubuhkan sebelum PROTON', 'Hanya satu syarikat kereta wujud sehingga kini', 'A', 'Bandingkan dua syarikat dan tahunnya.', 'PROTON dahulu pada 1983 dan PERODUA kemudian pada 1993, maka negara ada beberapa pengeluar kereta sendiri.'),
(841, 8, 'Pelancong asing mengagumi Gunung Kinabalu, Gua Niah dan Pulau Langkawi. Ketiga-tiga tempat ini mewakili keistimewaan yang mana?', 'Tapak dan bangunan bersejarah', 'Keharmonian dan keunikan budaya', 'Sukan, muzik dan pameran antarabangsa', 'Keindahan alam semula jadi', 'D', 'Gunung, gua dan pulau.', 'Gunung Kinabalu, Gua Niah dan Pulau Langkawi ialah contoh keindahan alam semula jadi.'),
(842, 8, 'Sebuah keluarga bandar menginap di rumah penduduk kampung dan mengikuti kerja di kebun. Apakah jenis pelancongan ini?', 'Pelancongan sukan permotoran', 'Pelancongan pameran maritim', 'Agropelancongan melalui konsep inap desa', 'Pelancongan tapak bersejarah sahaja', 'C', 'Fikirkan inap desa dan pertanian.', 'Inap desa bersama keluarga tempatan dengan aktiviti pertanian ialah agropelancongan.'),
(843, 8, 'Pembinaan jalan raya, jambatan dan kereta api yang terancang memberi kesan yang bagaimana kepada negara?', 'Menyebabkan pembangunan terhenti serta-merta', 'Mendorong kesinambungan pembangunan dan meningkatkan daya saing negara', 'Mengurangkan peluang perdagangan rakyat', 'Menjadikan e-dagang tidak berguna', 'B', 'Perhubungan moden menyokong pembangunan.', 'Perhubungan moden yang terancang mendorong kesinambungan pembangunan dan menyokong daya saing negara.'),
(844, 8, 'Seorang murid memilih membeli kuih buatan usahawan tempatan dan bukan makanan import. Apakah sumbangan tindakannya?', 'Membantu usahawan dan memperluaskan pasaran produk tempatan', 'Mengurangkan pendapatan negara', 'Menutup peluang pekerjaan rakyat', 'Melemahkan identiti negara', 'A', 'Fikirkan siapa yang mendapat manfaat.', 'Menyokong produk tempatan membantu usahawan, memperluaskan pasaran dan memajukan ekonomi negara.');
